var COMBO={"ISTJ>INTJ": {"karai": "앞을 내다보는 척하지만, 예상 밖 일이 터지면 제일 먼저 굳어버림.", "name": "전례를 사랑하는 미래 설계자", "atari": ["[[今:'5년 후 계획'을 이야기하면서도]], [[本:사실은 작년이랑 똑같은 방식이 제일 마음 편하다고 생각함]].", "[[今:새 아이디어 내는 회의 중에도]], [[本:머릿속 한구석에선 지난 자료 폴더를 몰래 열어 보고 있음]]."]}, "ISTJ>INTP": {"karai": "자유로운 영혼이라더니, 책상 서랍 속은 예전부터 라벨 붙여서 각 잡혀 있음.", "name": "마감은 지키는 길 잃은 연구자", "atari": ["[[今:궁금한 게 생기면 파고드느라 멈출 줄 모르면서]], [[本:제출일만큼은 몸이 알아서 기억함]].", "[[今:\"뭐, 어떻게든 되겠지\" 하면서]], [[本:집에 오면 내일 챙길 물건을 가지런히 늘어놓고 있음]]."]}, "ISTJ>ENTJ": {"karai": "든든한 리더 소리 들을 때마다, 퇴근길에 녹초 돼서 편의점 디저트 사 가는 중.", "name": "무대 뒤 출신 리더", "atari": ["[[今:회의에서 당당하게 진행하면서]], [[本:끝나는 순간 속으로 '빨리 혼자 있고 싶다'고 외치는 중]].", "[[今:큰 목표를 내걸지만]], [[本:진짜 불타오르는 건 세세한 절차를 하나씩 지워 나갈 때임]]."]}, "ISTJ>ENTP": {"karai": "틀을 깨는 캐릭터로 밀고 있지만, 사실 깨기 전에 틀부터 달달 외우는 모범생임.", "name": "규칙적인 청개구리", "atari": ["[[今:\"오히려 말이야\" 하고 논쟁을 걸어 놓고]], [[本:속으로는 전례대로 결론이 나길 바라고 있음]].", "[[今:분위기에 휩쓸려 새 기획에 올라탄 뒤]], [[本:한밤중에 혼자 리스크를 전부 적어 보다가 잠 못 이룸]]."]}, "ISTJ>INFJ": {"karai": "\"마음이 중요하지\"라더니, 지각 사유가 '마음'이면 그냥 안 봐줌.", "name": "매뉴얼을 품은 경청 달인", "atari": ["[[今:친구 고민 상담에는 깊이 끄덕여 주면서]], [[本:머릿속으로는 해결책을 항목별로 정리하고 있음]].", "[[今:사람 마음을 읽고 움직일 줄 알게 됐지만]], [[本:읽은 다음 대응은 역시 매뉴얼파임]]."]}, "ISTJ>INFP": {"karai": "몽글몽글한 사람인 줄 알지만, 빌려준 돈이랑 날짜는 원 단위까지 기억함.", "name": "꿈꾸는 경리 담당", "atari": ["[[今:좋아하는 영화 세계에 푹 빠져 있으면서도]], [[本:상영 시간이랑 돌아갈 전철 시간은 이미 계산 끝내 둠]].", "[[今:'나답게 살고 싶다'고 일기에 쓴 다음 날에도]], [[本:늘 같은 시간, 늘 같은 길로 출근하고 있음]]."]}, "ISTJ>ENFJ": {"karai": "사람 이끄는 건 잘하는데, 내 일정 꼬이게 하면 웃는 얼굴인데 눈이 안 웃음.", "name": "꼼꼼한 돌봄 담당", "atari": ["[[今:모두의 상담 역할을 맡아 주면서도]], [[本:사실은 빨리 집에 가서 정해 둔 저녁을 먹고 싶어 함]].", "[[今:후배를 격려하는 말은 뜨거운데]], [[本:그 격려 멘트를 미리 메모로 준비해 둠]]."]}, "ISTJ>ENFP": {"karai": "인싸 연기한 날 밤엔, 반동으로 늘 먹던 백반이랑 늘 보던 영상만 받아들임.", "name": "설렘을 결재 중인 사람", "atari": ["[[今:\"재밌겠다! 갈래!\" 하고 바로 대답한 뒤]], [[本:집에 와서 준비물이랑 예산을 진지한 얼굴로 찾아보고 있음]].", "[[今:새 취미에 줄줄이 손을 대지만]], [[本:하나같이 설명서를 첫 페이지부터 다 읽고 나서 시작함]]."]}, "ISTJ>ISTJ": {"karai": "\"전에도 이렇게 했으니까\"가 최강 말버릇. 새로운 방식 제안은 일단 한 번 흘려들음.", "name": "흔들림 없는 인간 시간표", "atari": ["아침 루틴을 10년째 안 바꿨고, 편의점 계산대 앞에서 살 것까지 정해져 있음.", "부탁받은 일은 마감 사흘 전에 내는 게 당연해서, 아슬아슬하게 내는 사람 마음을 모름."]}, "ISTJ>ISFJ": {"karai": "배려의 아이콘이라지만, 그 배려엔 매번 근거와 전례가 확실히 있음.", "name": "다정함도 정시 운행", "atari": ["[[今:남한테 맞춰서 \"괜찮아\"라고 말할 수 있게 됐지만]], [[本:마음속 노트에는 '예외'로 기록해 둠]].", "[[今:간식 돌리는 것도 능숙해졌지만]], [[本:개수랑 나눠 주는 순서는 미리 완벽하게 정해 둠]]."]}, "ISTJ>ESTJ": {"karai": "야무진 리더처럼 보이지만, 사람들 앞에서 말할 때마다 몰래 수명 깎는 중.", "name": "사교도 해내는 장인", "atari": ["[[今:회식 준비를 완벽하게 진행한 뒤]], [[本:2차는 안 가고 곧장 집에 가서 조용히 만족하고 있음]].", "[[今:사람들 앞에서 지시하는 건 익숙해졌지만]], [[本:사실 매번 메일로 다 끝내고 싶다고 생각함]]."]}, "ISTJ>ESFJ": {"karai": "모두에게 다정한 총무님이지만, 당일 파토 낸 사람 이름은 내년 명단에서 꼭 확인함.", "name": "센스 총무의 정체는 장인", "atari": ["[[今:생일 파티 분위기를 띄우면서]], [[本:속으로는 '케이크를 몇 시에 내야 일정대로 가나' 계산 중]].", "[[今:단톡방 답장은 빠르고 따뜻한데]], [[本:보내기 전에 세 번 다시 읽고 오타 확인함]]."]}, "ISTJ>ISTP": {"karai": "자유롭게 사는 척하지만, 갑자기 약속 바뀌면 하루 종일 기분 나쁜 게 얼굴에 다 드러남.", "name": "계획을 풀어 놓은 공구함", "atari": ["[[今:일정은 안 정하는 파가 됐다고 생각하지만]], [[本:여행지 화장실 위치만큼은 왠지 미리 찾아 둠]].", "[[今:기분 따라 손을 움직이게 됐지만]], [[本:쓴 도구는 꼭 제자리에 돌려놔야 마음이 놓임]]."]}, "ISTJ>ISFP": {"karai": "감성으로 산다지만, 최애 카페에선 같은 자리, 같은 메뉴에서 절대 안 움직임.", "name": "좋아하는 것도 시간표대로", "atari": ["[[今:'좋아서' 옷을 고르게 됐는데도]], [[本:사기 전에 세탁 표시랑 가격 비교는 확실히 끝냄]].", "[[今:기분 내서 방 배치를 바꾼 뒤]], [[本:결국 원래 배치가 최고라며 조용히 되돌려 놓음]]."]}, "ISTJ>ESTP": {"karai": "행동파처럼 보여도, 사실 그 과감함도 과거 성공 사례를 그대로 따라 하는 것뿐일 수 있음.", "name": "신중파 스릴 담당", "atari": ["[[今:\"일단 해 보자\"며 앞장서면서]], [[本:머릿속에서는 보험이랑 도망칠 길을 세 개 준비해 둠]].", "[[今:갑작스러운 약속에도 응할 수 있게 됐지만]], [[本:집에 와서 가계부를 열고 살짝 반성함]]."]}, "ISTJ>ESFP": {"karai": "파티 좋아하는 사람으로 보이지만, 속마음은 집에서 같은 드라마 정주행 또 하고 싶음.", "name": "분위기 메이커 겸 장부 담당", "atari": ["[[今:노래방에서 제일 먼저 불러 분위기를 띄운 뒤]], [[本:N빵 계산도 슬쩍 전부 맡고 있음]].", "[[今:\"지금을 즐기자!\"고 말한 다음 날 아침]], [[本:평소보다 30분 일찍 일어나서 어제 밀린 걸 만회하고 있음]]."]}, "ISFJ>INTJ": {"karai": "차가운 전략가인 척하지만, 지인들 생일은 폰 캘린더에 전원 등록되어 있음.", "name": "냉정한 척하는 오지랖", "atari": ["[[今:합리적으로 잘라 냈다고 생각한 일을]], [[本:결국 밤에 몰래 대신 처리해 주고 있음]].", "[[今:회의에서는 \"비효율적이에요\"라고 딱 잘라 말하면서]], [[本:들은 사람 표정을 집에 가서까지 신경 씀]]."]}, "ISFJ>INTP": {"karai": "남한테 관심 없는 척 장인. 근데 카톡 읽어놓고 답장 30분 고민하는 거 다 들킴.", "name": "논리로 감춘 오지랖", "atari": ["[[今:\"논리적으로 생각하면\" 하고 운을 떼면서]], [[本:결국 제일 곤란한 사람 편을 들고 있음]].", "[[今:관심 있는 걸 파기 시작하면 멈추질 못하지만]], [[本:친구들 최애 음식 리스트만큼은 한 번도 안 잊음]]."]}, "ISFJ>ENTJ": {"karai": "강한 리더 얼굴을 하고 있지만, 세게 말한 상대를 새벽까지 떠올리며 후회함.", "name": "박력 있는 간호 담당", "atari": ["[[今:팀을 이끌고 숫자로 몰아붙일 줄 알게 됐는데]], [[本:몰아붙인 뒤엔 간식 사러 뛰어가고 있음]].", "[[今:\"내가 정할게\"라고 말한 순간]], [[本:속으로는 반대한 사람 없나 한 명 한 명 얼굴을 살피고 있음]]."]}, "ISFJ>ENTP": {"karai": "궤변으로 분위기 띄우는 게 특기가 됐지만, 사실 아무한테도 미움받기 싫은 마음 한가득임.", "name": "태클 담당 보건실", "atari": ["[[今:\"오히려 말이야\" 하고 논쟁을 달군 뒤]], [[本:심하게 말한 상대한테만 따로 수습 카톡을 보내고 있음]].", "[[今:새로운 거에 확 달려드는 캐릭터가 됐지만]], [[本:본가 된장국 맛이 바뀌면 누구보다 먼저 알아챔]]."]}, "ISFJ>INFJ": {"karai": "깊이 있는 사람이란 말 자주 듣지만, 사실 걱정의 범위가 계속 넓어지는 것뿐임.", "name": "미래까지 걱정하는 사람", "atari": ["[[本:친구의 지금 고민뿐 아니라]], [[今:3년 뒤 일까지 상상하며 혼자 마음 아파함]].", "[[今:이상을 이야기하게 됐지만]], [[本:손은 어느새 눈앞의 설거지를 하고 있음]]."]}, "ISFJ>INFP": {"karai": "섬세한 예술가 기질인 척하지만, 사실 누군가에게 도움이 안 되면 불안한 사람임.", "name": "준비성을 깜빡한 몽상가", "atari": ["[[今:좋아하는 이야기에 몰입하면서도]], [[本:가족 귀가가 늦으면 이야기고 뭐고 안절부절못함]].", "[[今:'내 페이스대로' 하기로 정했는데]], [[本:누가 부탁하면 바로 일정을 다 비워 버림]]."]}, "ISFJ>ENFJ": {"karai": "든든한 선배 캐릭터가 몸에 뱄지만, 기대받는 피로를 아무한테도 말 못 하는 게 최대 약점.", "name": "무대에 오른 숨은 조력자", "atari": ["[[今:모두 앞에서 격려의 말을 할 수 있게 됐지만]], [[本:사실은 뒤에서 조용히 차 나르는 게 더 좋음]].", "[[今:사람을 모아 이끄는 역할을 맡을 때마다]], [[本:집에 오면 불도 안 켜고 한참 앉아 있음]]."]}, "ISFJ>ENFP": {"karai": "흥으로 사는 얼굴을 하고 있지만, 일정이 갑자기 바뀌면 누구보다 먼저 마음이 술렁임.", "name": "신나게 노는 지킴이", "atari": ["[[今:누구보다 신나게 놀고 있으면서]], [[本:눈 끝으로는 무리에 못 낀 사람을 계속 찾고 있음]].", "[[今:즉흥으로 여행을 정해 놓고]], [[本:출발 전날 밤엔 전원 몫의 멀미약을 가방에 챙겨 둠]]."]}, "ISFJ>ISTJ": {"karai": "칼같은 사람으로 통하지만, 엄하게 말한 날 밤엔 상대한테 할 변명을 머릿속으로 백 번 되뇜.", "name": "정을 봉인한 꼼꼼이", "atari": ["[[今:규칙대로 거절할 수 있게 됐지만]], [[本:거절하고 나서 상대 뒷모습을 보며 마음이 콕 찔림]].", "[[今:일할 때는 \"규정이라서요\"라고 딱 잘라 말하면서]], [[本:집에서는 가족 입맛 맞춰 메뉴를 매일 바꾸고 있음]]."]}, "ISFJ>ISFJ": {"karai": "\"괜찮아\"가 말버릇. 근데 진짜 안 괜찮을 때도 같은 얼굴로 말해서 아무도 모름.", "name": "타고난 수호신", "atari": ["누가 재채기하는 순간 이미 가방에서 휴지를 꺼내고 있음. 생각보다 손이 먼저임.", "친구가 1년 전에 말한 \"이거 좋아\"를 기억해 뒀다가, 생일에 쓱 건네서 깜짝 놀라게 함."]}, "ISFJ>ESTJ": {"karai": "야무진 얼굴을 하고 있지만, 사실 누가 \"고마워\" 한마디 해주길 바라며 열심히 하는 중.", "name": "진행 잘하는 힐링 캐릭터", "atari": ["[[今:일정표를 짜서 모두에게 지시하면서]], [[本:말투가 세게 들리진 않았나 어미를 몇 번이나 고치고 있음]].", "[[今:\"정한 건 지켜 주세요\"라고 말할 위치가 됐지만]], [[本:못 지킨 사람 사정을 그만 들어 주고 있음]]."]}, "ISFJ>ESFJ": {"karai": "부르면 거절 못 하는 걸 사교성으로 오해받아서, 정신 차려보면 주말 일정이 꽉 차 있음.", "name": "북적이는 자리의 탕비실 담당", "atari": ["[[今:회식 총무를 멋지게 해낸 귀갓길]], [[本:이어폰 끼고 아무하고도 말 안 하는 시간을 필사적으로 되찾는 중]].", "[[今:무리 한가운데서 웃고 있지만]], [[本:사실은 소수끼리 차 한잔하는 정도가 딱 좋음]]."]}, "ISFJ>ISTP": {"karai": "쿨하게 혼자 다니는 것처럼 보여도, 사실 누가 나한테 의지할 때가 제일 기쁨.", "name": "말없는 수리공", "atari": ["[[今:\"딱히 신경 안 써\"라고 무심하게 말하면서]], [[本:고장 난 친구 자전거를 말없이 고쳐 주고 있음]].", "[[今:계획 안 세우는 가벼움을 익혔지만]], [[本:냉장고 속 유통기한만큼은 확실히 꿰고 있음]]."]}, "ISFJ>ISFP": {"karai": "마이페이스 선언해놓고, 남들 일정 맞춰주다 보면 결국 또 진행 담당.", "name": "자유롭게 헌신하는 사람", "atari": ["[[今:그날 기분 따라 움직이게 됐지만]], [[本:누가 곤란해하면 기분보다 몸이 먼저 움직임]].", "[[今:내 '좋아'를 우선해도 된다고 생각하게 됐지만]], [[本:고른 소품은 대부분 누군가에게 줄 선물임]]."]}, "ISFJ>ESTP": {"karai": "호탕한 캐릭터로 밀고 있지만, 사실 한 번 실수하면 몇 년씩 곱씹는 타입.", "name": "몸으로 부딪치는 걱정쟁이", "atari": ["[[今:기세 좋게 뛰어든 다음]] [[本:\"아까 말투 괜찮았어?\" 하고 작은 목소리로 확인하고 있음]].", "[[今:스릴을 즐기는 얼굴을 하면서]], [[本:밴드랑 위장약은 늘 파우치에 상비해 둠]]."]}, "ISFJ>ESFP": {"karai": "밝은 분위기 메이커인 줄 알지만, 집에 오면 혼자 반성회 열고 오늘 한 말 전부 복기함.", "name": "분위기 메이커 겸 구급반", "atari": ["[[今:신나게 춤추며 분위기를 띄우면서]], [[本:과음한 사람 물이랑 귀가 택시까지 챙기고 있음]].", "[[今:\"오늘은 즐기는 사람이 이기는 거야\" 하면서]], [[本:내일 준비 안 된 게 머릿속을 떠나지 않음]]."]}, "INFJ>INTJ": {"karai": "차갑게 보이는 데 능숙해졌지만, 영화 예고편만 보고도 그냥 울음.", "name": "논리 갑옷을 입은 공감러", "atari": ["[[今:\"감정론은 필요 없어요\"라고 잘라 말한 회의 뒤]], [[本:울 것 같던 사람 생각을 계속하고 있음]].", "[[今:효율로 판단한다고 생각하지만]], [[本:마지막 결정타는 늘 '이 사람이 상처받지 않을까'임]]."]}, "INFJ>INTP": {"karai": "남한테 관심 없는 척하면서, 상대가 한 말 속뜻을 사흘 정도 고민함.", "name": "사람 마음을 연구하는 사람", "atari": ["친구 연애 상담을 [[今:어느새 심리학 논문 읽는 눈으로 분석하고 있음]].", "[[今:생각에 빠져 약속을 흘려보내게 됐는데]], [[本:사람과의 약속만큼은 전날부터 마음의 준비를 함]]."]}, "INFJ>ENTJ": {"karai": "센 리더로 통하지만, 단 한 명의 차가운 눈빛에 일주일 내내 다운될 수 있음.", "name": "이상을 짊어진 사령탑", "atari": ["[[今:숫자로 사람을 움직일 줄 알게 됐지만]], [[本:사실은 '이 일엔 의미가 있다'는 말을 듣고 싶음]].", "[[今:당당하게 결단 내리는 모습이 잘 어울리게 됐지만]], [[本:정하고 나서 혹시 두고 온 사람 없나 혼자 되짚어 봄]]."]}, "INFJ>ENTP": {"karai": "입으로는 비꼬지만, 들은 상대가 웃었는지 확인할 때까지 마음이 안 놓임.", "name": "토론 좋아하는 숨은 성인", "atari": ["[[今:일부러 반대 의견을 내서 토론을 달구면서]], [[本:사실은 다 같이 사이좋게 마무리되는 결말을 바라고 있음]].", "[[今:사람들 앞에선 수다스럽고 가볍지만]], [[本:새벽에 '사는 의미' 같은 걸 검색해 버리는 밤이 있음]]."]}, "INFJ>INFJ": {"karai": "참고 또 참다가, 어느 날 갑자기 소리 없이 손절하는 게 제일 무서움.", "name": "다 꿰뚫어 보는 조용한 사람", "atari": ["방에 들어서는 순간 누구랑 누가 사이 나쁜지 알아채고, 그대로 조용히 자리를 고름.", "상대가 말하기도 전에 원하는 걸 알아채서, 선물 고르다 실패한 적이 거의 없음."]}, "INFJ>INFP": {"karai": "자유롭게 사는 줄 알았는데, 사실 어질러진 방 볼 때마다 조용히 자기혐오 중.", "name": "계획을 잃어버린 예언자", "atari": ["[[本:앞을 내다보는 건 잘하는데]], [[今:기분이 안 나면 아무것도 손에 안 잡혀서]] 내다본 미래를 못 따라감.", "[[今:자기만의 세계에 틀어박히는 시간이 늘었지만]], [[本:소중한 사람의 이상 신호만큼은 멀리서도 바로 알아챔]]."]}, "INFJ>ENFJ": {"karai": "기대받는 걸 좋아하는 얼굴이지만, 사실 모두의 이야기를 너무 성실히 들어서 매일 녹초됨.", "name": "모두의 상담실, 밤엔 영업 종료", "atari": ["[[今:낮에는 모두의 상담 역할로 대활약하지만]], [[本:밤엔 알림 끄고 아무하고도 말 안 하는 시간이 필요함]].", "[[今:남 격려하는 건 잘하면서]], [[本:내 고민은 \"별거 아니야\" 하고 아무한테도 말 안 함]]."]}, "INFJ>ENFP": {"karai": "밝은 사람이란 말을 계속 들어서, 우울한 날에도 밝게 구는 게 습관이 됨.", "name": "설렘으로 위장한 관찰자", "atari": ["[[今:누구하고든 금방 친해지지만]], [[本:마음의 문 안쪽까지 들일 수 있는 사람은 사실 손에 꼽을 정도임]].", "[[今:즉흥적으로 움직이는 것처럼 보여도]], [[本:그 즉흥은 며칠 전부터 머릿속에서 품어 온 것임]]."]}, "INFJ>ISTJ": {"karai": "규칙 잘 지키는 모범생인 척하면서, 사실 세상 돌아가는 구조 자체에 줄곧 납득 못 하는 중.", "name": "전례 뒤에 숨은 이상가", "atari": ["[[今:정해진 절차대로 일을 해내면서]], [[本:속으로는 '사실 더 잘할 수 있는데' 생각하고 있음]].", "[[今:현실적인 사람으로 통하지만]], [[本:출근길 전철 창밖을 보며 거대한 이야기를 공상하곤 함]]."]}, "INFJ>ISFJ": {"karai": "조용하고 온화해 보여도, 사실 누구보다 고집 센 '마땅히 이래야 함'을 품고 있음.", "name": "땅에 발 붙인 몽상가", "atari": ["[[今:눈앞의 집안일과 부탁받은 일을 담담히 해내면서]], [[本:머릿속으로는 10년 뒤 이상적인 삶을 그리고 있음]].", "[[今:사람 챙기는 게 자연스러워졌지만]], [[本:챙기면서 상대 속마음까지 몰래 읽어 내고 있음]]."]}, "INFJ>ESTJ": {"karai": "일잘러를 완벽하게 연기해내고, 주말엔 커튼 치고 누구 연락도 안 받음.", "name": "일정표를 든 철학자", "atari": ["[[今:회의를 시간 맞춰 진행하면서]], [[本:문득 '이 회의는 대체 뭘 위해 있는 걸까' 생각하고 있음]].", "[[今:척척 지시할 수 있게 됐지만]], [[本:세게 말한 상대 표정을 자기 전에 몇 번이고 떠올림]]."]}, "INFJ>ESFJ": {"karai": "모두에게 너무 잘 맞춰줘서, 내가 진짜 뭘 하고 싶은지 나도 모르게 되기 쉬움.", "name": "연회장에 앉은 신선", "atari": ["[[今:회식 자리 배치를 짤 때]], [[本:누구랑 누구를 떨어뜨려야 할지까지 한눈에 꿰뚫고 배치함]].", "[[今:왁자지껄한 무리 한가운데서 끄덕이면서도]], [[本:마음은 어딘가 먼 조용한 곳을 여행 중]]."]}, "INFJ>ISTP": {"karai": "건조한 척하지만, 사실 딱 한 사람만큼은 나를 깊이 알아줬으면 함.", "name": "말없이 깊은 손재주꾼", "atari": ["[[今:묵묵히 손만 움직이는 쿨한 사람으로 보여도]], [[本:사실 주변 공기 변화를 전부 느끼고 있음]].", "[[今:\"어떻게든 되겠지\" 하며 가볍게 행동하지만]], [[本:밤이 되면 인생의 의미를 생각하느라 잠 못 듦]]."]}, "INFJ>ISFP": {"karai": "자유로운 감성러를 자처해도, 결국 남들 마음 먼저 챙기느라 내 '좋아'는 뒷전.", "name": "감성으로 사는 예측가", "atari": ["[[今:마음에 드는 음악이나 풍경에 마음을 맡기면서도]], [[本:그 너머의 의미까지 그만 생각해 버림]].", "[[今:지금을 즐기는 법을 배웠지만]], [[本:즐거운 순간에도 '이것도 언젠가 끝나겠지' 생각함]]."]}, "INFJ>ESTP": {"karai": "호탕하게 웃고 있지만, 속마음은 아무에게도 안 보여주는 일기장처럼 잠겨 있음.", "name": "기세 타는 과몰입 해석러", "atari": ["[[今:그 자리 분위기 타고 뛰어든 다음]], [[本:귀갓길에 '그 사람 사실 싫었을지도' 하고 깊이 해석하고 있음]].", "[[今:행동파라는 말을 듣지만]], [[本:사실 움직이기 전에 순식간에 상대 반응을 몇 가지나 예측해 둠]]."]}, "INFJ>ESFP": {"karai": "분위기 너무 띄운 날 이후엔, 사흘은 집에서 충전해야 원래의 나로 돌아옴.", "name": "무대 위의 지켜보는 사람", "atari": ["[[今:그 자리 주인공으로 분위기를 띄우면서]], [[本:무리 밖에서 심심해하는 사람을 꼭 찾아냄]].", "[[今:\"재밌으면 됐지\" 하면서]], [[本:그 재미에 의미가 있는지 몰래 생각하고 있음]]."]}, "INTJ>INTJ": {"karai": "내 생각이 맞다고 너무 확신해서, 설명하는 수고를 자주 생략하고 오해받음.", "name": "최단 경로 외길 인생", "atari": ["이야기를 들으면서 결론은 진작 나와 있고, 상대가 같은 답에 도착하길 조용히 기다리는 중.", "휴일 일정도 효율 중심으로 짜서, 친구한테 \"여행이 아니라 작전이네\" 소리를 자주 들음."]}, "INTJ>INTP": {"karai": "느긋한 척하지만, 남이 늘어지는 꼴엔 누구보다 날카롭게 태클 검.", "name": "결론을 묵혀 두는 전략가", "atari": ["[[本:답은 이미 보이는데]] [[今:\"조금만 더 찾아보고\" 하면서 검색 탭을 계속 늘리고 있음]].", "[[今:계획 없는 자유로운 생활을 동경하다가]], [[本:정신 차려 보면 '계획 안 세우는 계획'을 짜고 있음]]."]}, "INTJ>ENTJ": {"karai": "사교적인 리더를 훌륭히 소화하지만, 스몰토크 시간만큼은 매번 속으로 지옥이라 생각함.", "name": "최전선에 나선 참모", "atari": ["[[今:리더로서 당당하게 말할 수 있게 됐지만]], [[本:사실은 자료만 건네고 집에 가고 싶음]].", "[[今:모두를 끌어들이는 힘은 생겼지만]], [[本:끌어들일 때마다 '혼자 하는 게 빠른데' 하고 속으로 중얼거림]]."]}, "INTJ>ENTP": {"karai": "아무 말이나 하는 것처럼 보여도, 상대 반박 패턴까지 미리 다 준비해 놨음.", "name": "계획적인 즉흥러", "atari": ["[[今:\"오히려 말이야\" 하며 자유롭게 이야기를 넓히지만]], [[本:사실 그 탈선도 최종 결론으로 가기 위한 우회로임]].", "[[今:새 아이디어를 줄줄이 내놓는 한편]], [[本:실행할 건 결국 딱 하나라고 처음부터 정해 둠]]."]}, "INTJ>INFJ": {"karai": "공감 잘하는 척하지만, 같은 하소연 세 번째쯤부터 눈이 점점 멀어짐.", "name": "다정함을 배운 합리주의자", "atari": ["[[今:상대 마음에 공감해 줄 수 있게 됐지만]], [[本:공감하면서도 머리는 해결까지의 최단 거리를 계산 중]].", "[[今:\"힘들었겠다\"라고 말할 수 있게 됐지만]], [[本:그 뒤에 개선안 세 개를 덧붙이지 않고는 못 배김]]."]}, "INTJ>INFP": {"karai": "섬세한 몽상가를 자처해도, 비효율적인 사람 보면 표정에 드러나는 건 못 숨김.", "name": "효율파 로맨티스트", "atari": ["[[今:이상이나 꿈 이야기를 좋아하게 됐지만]], [[本:정신 차려 보면 그 꿈을 이룰 방법을 공정표로 만들고 있음]].", "[[今:기분 내키는 대로 보내는 휴일을 즐기면서도]], [[本:속으로는 '이 시간에 뭘 할 수 있었나'를 세고 있음]]."]}, "INTJ>ENFJ": {"karai": "잘 챙겨주는 선배로 존경받지만, 속마음은 다들 알아서 생각하고 움직여 주는 게 제일 좋음.", "name": "작전 있는 응원단장", "atari": ["[[今:후배를 뜨겁게 격려하면서]], [[本:그 격려 방식이 가장 효과적인지 냉정하게 계산하고 있음]].", "[[今:모두의 중심에 있지만]], [[本:사실은 누구랑 누구를 붙여야 성과가 날지 관찰하고 있을 뿐임]]."]}, "INTJ>ENFP": {"karai": "천진난만해 보이는 데 능하지만, 흥만 있는 기획엔 속으로 즉시 불합격 때림.", "name": "설렘을 분석하는 사람", "atari": ["[[今:\"그거 완전 최고!\" 하고 들뜬 직후]], [[本:그 아이디어 약점을 머릿속에서 세 개나 찾아내 버림]].", "[[今:재밌는 것마다 달려드는 캐릭터지만]], [[本:달려들기 전에 손익 계산은 대충 끝내 둠]]."]}, "INTJ>ISTJ": {"karai": "성실한 현실파로 통하지만, 속으로는 회사 시스템을 통째로 갈아엎을 계획 짜는 중.", "name": "전례를 따르는 혁명가", "atari": ["[[今:정해진 절차를 지키며 꼼꼼히 일하면서]], [[本:머릿속으로는 그 방식의 개선안을 몇 번이고 고쳐 쓰고 있음]].", "[[今:현실적인 일솜씨로 신뢰받지만]], [[本:사실은 5년 뒤 큰 그림 그리는 게 더 좋음]]."]}, "INTJ>ISFJ": {"karai": "착하다는 말 듣지만, 그 착함은 귀찮은 일을 최소화하기 위한 전략이기도 함.", "name": "묵묵히 헌신하는 천재 군사", "atari": ["[[今:부탁받은 일을 웃으며 맡으면서]], [[本:속으로는 '이 부탁 방식, 비효율적이네' 하고 냉정하게 채점 중]].", "[[今:주변에 맞춰 얌전히 있지만]], [[本:사실은 전부 내 방식대로 다시 하고 싶어서 근질근질함]]."]}, "INTJ>ESTJ": {"karai": "꼼꼼한 현장 사람처럼 보여도, 규칙 대부분엔 속으로 '이거 의미 있음?' 하는 중.", "name": "현장에 내려온 전략가", "atari": ["[[今:세세한 일정표를 짜서 모두를 움직이면서]], [[本:사실은 더 큰 방향성 이야기를 하고 싶어 함]].", "[[今:사람들 앞에서 지시하는 게 일상이 됐지만]], [[本:점심시간엔 아무하고도 말 안 하고 혼자 보내기로 정해 둠]]."]}, "INTJ>ESFJ": {"karai": "누구에게나 다정한 얼굴이지만, 속 독설 메모장이 꽤 두꺼워져 있음.", "name": "웃는 총무의 참모 본부", "atari": ["[[今:모두의 취향을 물어 모임을 열면서도]], [[本:사실은 혼자 다 정하는 게 빠르다는 걸 알고 있음]].", "[[今:단톡방에 밝게 이모티콘을 보내면서]], [[本:머릿속에선 누가 안 올지 이미 예측해 둠]]."]}, "INTJ>ISTP": {"karai": "즉흥파인 척하지만, 사실 몇 수 앞까지 안 읽어두면 불안해서 잠 못 잠.", "name": "설계도를 버린 만들기 덕후", "atari": ["[[今:떠오르는 대로 손을 움직이게 됐지만]], [[本:만들면서 완성까지의 순서를 머릿속에 탄탄히 짜고 있음]].", "[[今:일정 없이 가볍게 지내는 걸 즐기면서도]], [[本:남의 허술한 일 처리만큼은 아무래도 눈에 밟힘]]."]}, "INTJ>ISFP": {"karai": "몽글몽글한 분위기란 말 듣지만, 진지하게 토론 붙이면 누구보다 자비 없음.", "name": "감성으로 무장한 이론파", "atari": ["[[今:좋아하는 걸 직감으로 고르는 것처럼 보여도]], [[本:사실 리뷰랑 비교표를 며칠씩 정독함]].", "[[今:남한테 다정하게 맞춰 줄 수 있게 됐지만]], [[本:속으로는 앞뒤 안 맞는 말에 조용히 태클 거는 중]]."]}, "INTJ>ESTP": {"karai": "추진력 있다는 말에 으쓱하지만, 사실 예상 밖의 일이 제일 약함.", "name": "사전 조사 끝낸 행동파", "atari": ["[[今:그 자리 분위기대로 움직이는 것처럼 보여도]], [[本:사실 전날 밤에 전부 시뮬레이션해 둠]].", "[[今:사람들이랑 떠드는 것도 즐길 수 있게 됐지만]], [[本:귀갓길엔 오늘 대화에서 얻은 정보를 머릿속에서 다시 정리하고 있음]]."]}, "INTJ>ESFP": {"karai": "분위기 담당 풀파워로 해내고 나서, 혼자 되는 순간 전원 꺼진 듯 말이 없어짐.", "name": "분위기 메이커의 냉철한 두뇌", "atari": ["[[今:회식에서 제일 신나 있으면서]], [[本:머리 한구석에선 막차랑 내일 일정 역산이 계속 돌아가고 있음]].", "[[今:\"지금 즐거우면 됐지\" 하고 웃으면서]], [[本:그 즐거움이 미래의 뭐로 이어질지 그만 생각해 버림]]."]}, "ISTP>INTJ": {"karai": "전략가처럼 말하지만, 사실 귀찮은 단계를 줄이고 싶을 뿐일 수 있음.", "name": "계획서도 쓸 줄 아는 장인", "atari": ["[[本:사실은 만져 보면서 익히고 싶은데]], [[今:지금은 전체 설계도부터 그리고 움직이는 버릇이 생김]].", "[[今:5년 계획을 세운 그 주말에]], [[本:눈에 띈 공구를 충동구매하고 일정을 무너뜨리고 있음]]."]}, "ISTP>INTP": {"karai": "다 찾아본 시점에서 만족해서, 도착한 공구 택배 상자는 아직 한 번도 안 뜯음.", "name": "손보다 검색이 먼저인 장인", "atari": ["[[本:예전엔 분해해서 확인했는데]], [[今:지금은 분해하기 전에 리뷰를 세 시간 읽고 있음]].", "[[本:'일단 해 보자'가 입버릇이었는데]], [[今:지금은 논리가 맞아떨어질 때까지 손이 멈춤]]."]}, "ISTP>ENTJ": {"karai": "리더 하는 이유가, 남한테 맡기고 기다리는 게 제일 스트레스라서일 수도 있음.", "name": "진행 역할을 떠맡은 외로운 늑대", "atari": ["[[今:회의에서는 \"그럼 제가 정할게요\"라고 해 놓고]], [[本:끝나는 순간 혼자 묵묵히 작업으로 돌아가고 싶어 함]].", "[[今:팀 목표를 이야기할 땐 뜨거운데]], [[本:회식 제안은 매번 그럴듯한 이유로 거절하고 있음]]."]}, "ISTP>ENTP": {"karai": "말빨이 늘어난 만큼, 손 안 움직이는 핑계도 늘었음.", "name": "토론도 되는 과묵한 장인", "atari": ["[[今:\"오히려 말이야\" 하며 이야기를 넓혀 분위기를 띄운 뒤]], [[本:귀갓길엔 한동안 아무하고도 말하기 싫음]].", "[[本:사실 말없이 고치면 끝날 일인데]], [[今:요즘은 그만 고치는 법의 이론부터 늘어놓게 됨]]."]}, "ISTP>INFJ": {"karai": "눈치 빠른 사람처럼 보여도, 눈치챈 걸 말로 하기 귀찮아서 가만있는 날도 있음.", "name": "배려를 배운 수리공", "atari": ["[[今:남의 고민을 조용히 들어 주면서]], [[本:머리 한구석에선 '그래서 원인이 어디야?' 하고 분해하고 있음]].", "[[今:상대 마음을 미리 읽게 됐지만]], [[本:사실은 그냥 말해 주는 게 훨씬 편함]]."]}, "ISTP>INFP": {"karai": "나를 찾는 여행 중이지만, 사실 손만 움직이면 사흘이면 찾을 타입.", "name": "꿈도 꾸게 된 장인", "atari": ["[[本:현실적인 판단이 특기였는데]], [[今:요즘은 '이게 의미가 있나' 생각하다 손이 멈추는 밤이 있음]].", "[[今:좋아하는 영화 얘기만 나오면 갑자기 뜨거워지지만]], [[本:원래는 수리 영상을 훨씬 더 좋아했음]]."]}, "ISTP>ENFJ": {"karai": "잘 챙겨준다는 말 들을 때마다, 속으로 '혼자 하는 게 빠른데' 세 번 중얼거림.", "name": "오지랖으로 이직한 외로운 늑대", "atari": ["[[今:후배 상담에 진심으로 응해 주면서]], [[本:속으로는 '그거 만져 보면 알아' 하고 생각하고 있음]].", "[[今:모두의 일정을 맞춰 이벤트를 기획해 놓고]], [[本:당일 제일 먼저 집에 가고 싶은 건 본인임]]."]}, "ISTP>ENFP": {"karai": "하이텐션 캐릭터로 통하지만, 배터리 방전된 얼굴은 가족만 앎.", "name": "설렘을 알게 된 과묵한 사람", "atari": ["[[今:새 취미에 \"최고!\" 하며 들뜨지만]], [[本:오래 가는 건 결국 손 쓰는 종류뿐임]].", "[[今:누구하고든 금방 친해질 수 있게 됐는데]], [[本:카톡 답장은 여전히 한마디로 끝남]]."]}, "ISTP>ISTJ": {"karai": "꼼꼼해 보이지만, 일정표 뒷면엔 '내키면'이 잔뜩 적혀 있음.", "name": "준비성을 익힌 변덕쟁이 장인", "atari": ["[[今:마감 전에 꼬박꼬박 내고 있지만]], [[本:사실은 막판 집중력으로 한 번에 끝내는 게 체질에 맞음]].", "[[今:매뉴얼대로 진행하면서]], [[本:'이 절차, 두 개는 생략할 수 있는데' 하고 매번 생각함]]."]}, "ISTP>ISFJ": {"karai": "배려왕이란 말 듣지만, 눈치 보는 것보다 기계 고치는 게 훨씬 자신 있음.", "name": "다정함으로 움직이는 공구함", "atari": ["[[今:부탁을 거절 못 하게 됐지만]], [[本:사실은 방법만 넘겨주면 혼자 끝내고 싶음]].", "[[今:모두의 컨디션을 챙기면서]], [[本:본인 몸 상태는 '언젠가 낫겠지' 하고 방치하고 있음]]."]}, "ISTP>ESTJ": {"karai": "규칙에 엄한 사람이 됐지만, 예전엔 규칙 빈틈 제일 열심히 찾던 쪽이었음.", "name": "현장 감독이 된 자유인", "atari": ["[[今:팀 진행 상황은 꼼꼼히 관리하면서]], [[本:내 작업만큼은 그때그때 기분대로 하고 싶음]].", "[[今:아침 조회에서 척척 지시한 뒤]], [[本:점심시간엔 혼자 차 안에 틀어박혀 있음]]."]}, "ISTP>ESFJ": {"karai": "모두의 돌봄 담당처럼 보여도, 사실 '일정 짜기'라는 퍼즐을 즐기는 것뿐.", "name": "총무도 해내는 숨은 장인", "atari": ["[[今:회식 장소 고르기부터 계산까지 완벽하게 해내고]], [[本:2차 제안만큼은 스르륵 빠져나감]].", "[[今:단톡방에 이모티콘으로 성실히 반응하면서도]], [[本:속마음은 '읽음 표시 보면 알잖아'임]]."]}, "ISTP>ISTP": {"karai": "믿음직하지만, \"어떻게 한 거야?\" 물으면 \"그냥\"밖에 안 돌아옴.", "name": "말없이 고치는 뼛속까지 장인", "atari": ["설명서 안 읽고 조립했는데, 왠지 제일 깔끔하게 완성해 버림.", "곤란한 사람을 보면 말보다 손이 먼저 나가서 알아서 고쳐 놓음."]}, "ISTP>ISFP": {"karai": "감성파라더니, 결국 스펙표도 몰래 다 보고 있음.", "name": "감각으로 고르는 장인", "atari": ["[[本:성능으로 고르던 도구를]], [[今:요즘은 색감이랑 손맛으로 고르고 있음]].", "[[本:논리로 받아칠 수 있는 상황에서도]], [[今:상대 얼굴 보고 '뭐, 됐다' 하고 삼키게 됨]]."]}, "ISTP>ESTP": {"karai": "행동파 캐릭터가 몸에 뱄지만, 사실 아무도 안 부르는 휴일을 마음 한구석에서 기다림.", "name": "사람들 앞에 나선 장인", "atari": ["[[今:기분 따라 놀 약속을 마구 잡지만]], [[本:세 번째쯤에서 갑자기 혼자만의 시간이 그리워짐]].", "[[今:많은 사람 앞에서 말하는 것도 아무렇지 않게 됐는데]], [[本:건배가 끝나면 조용히 구석 자리로 이동하고 있음]]."]}, "ISTP>ESFP": {"karai": "즐거워 보이지만, 그 웃음의 80%는 '분위기 조용해지면 귀찮음'으로 이루어져 있음.", "name": "분위기 메이커도 되는 장인", "atari": ["[[今:무드메이커 노릇을 하면서]], [[本:속으로는 '빨리 집에 가서 작업 이어 하고 싶다' 생각하고 있음]].", "[[今:친구 얘기에 과하게 리액션하면서]], [[本:상담의 답은 이미 한 줄로 나와 있음]]."]}, "ISFP>INTJ": {"karai": "냉철한 판단인 척하지만, 결정타는 대개 '왠지 좋아서'임.", "name": "계획 세우는 감성파", "atari": ["[[今:효율과 근거로 이야기를 끌고 가면서]], [[本:자료 폰트랑 배색만큼은 절대 양보 못 함]].", "[[今:장기 계획을 완벽하게 세워 놓고]], [[本:마음이 움직이는 순간 전부 백지로 돌리고 싶어짐]]."]}, "ISFP>INTP": {"karai": "논리파를 자처하지만, 맘에 안 드는 의견엔 논리보다 얼굴이 먼저 반응함.", "name": "논리를 걸친 기분파", "atari": ["좋아하는 걸 이야기할 때 [[今:마음보다 '왜 좋은지' 분석이 먼저 입에서 나오게 됨]].", "[[今:가구 하나 고르는 데 비교 사이트를 순회하고]], [[本:마지막엔 첫눈에 반한 첫 번째 후보를 삼]]."]}, "ISFP>ENTJ": {"karai": "센 사람으로 보이고 싶은 마음이, 가끔 센 사람 성대모사가 됨.", "name": "리더로 변신한 섬세한 사람", "atari": ["[[今:회의에선 단호하게 결단하면서]], [[本:집에 오면 '너무 심했나' 하고 혼자 반성회가 시작됨]].", "[[今:목표와 숫자로 사람을 움직이면서]], [[本:사실은 다들 편하게 지내고 있는지가 신경 쓰임]]."]}, "ISFP>ENTP": {"karai": "태클 담당으로 자리 잡았지만, 내가 진지하게 부정당하면 일주일 끌고 감.", "name": "말발이 늘어난 감성파", "atari": ["[[今:토론에선 \"오히려 말이야\" 하고 파고드는데]], [[本:말로 이긴 상대 얼굴을 밤까지 떠올리고 있음]].", "[[今:아이디어를 줄줄이 내며 분위기를 띄우면서도]], [[本:사실은 하나를 차분히 손으로 만들어 보고 싶음]]."]}, "ISFP>INFJ": {"karai": "의미심장한 한마디 해놓고, 그 의미를 나중에 본인도 생각해 봄.", "name": "앞을 읽게 된 자유인", "atari": ["[[今:남의 기분을 미리 읽고 챙기게 됐지만]], [[本:사실은 그 순간 기분대로 움직이고 싶음]].", "[[今:다음 달 일정까지 다이어리에 적으면서]], [[本:마음은 '오늘 노을 예쁘다'에 빼앗겨 있음]]."]}, "ISFP>INFP": {"karai": "이상을 말하는 시간이 늘어난 만큼, 예전처럼 손으로 만드는 시간은 줄었음.", "name": "공상에 빠지게 된 감각파", "atari": ["[[本:눈앞의 것을 즐기는 게 특기였는데]], [[今:요즘은 '이건 뭘 위한 거지?' 하고 생각에 잠기기 일쑤]].", "[[本:산책하다 발견한 꽃 한 송이에서]] [[今:왠지 거대한 이야기를 망상하다 보니 집에 도착해 있음]]."]}, "ISFP>ENFJ": {"karai": "기대받는 게 좋아서 너무 많이 떠맡고, 내 '좋아'는 계속 뒷전.", "name": "모두를 위해 애쓰는 혼자파", "atari": ["[[今:모두의 상담 역할을 맡으면서도]], [[本:사실은 좋아하는 음악 들으며 혼자 보내고 싶음]].", "[[今:친구 생일 파티를 기획해서 대성공했는데]], [[本:다음 날엔 아무도 안 만나고 앓아누워 있음]]."]}, "ISFP>ENFP": {"karai": "흥 많은 사람처럼 보여도, 진짜 부르고 싶은 사람한텐 먼저 연락 못 한 채로 있음.", "name": "사람들 속에 뛰어든 감성파", "atari": ["[[今:처음 본 사람한테도 웃으며 말을 걸 수 있게 됐지만]], [[本:귀갓길 이어폰이 생명줄임]].", "설렘으로 움직이는 건 예나 지금이나 같음. 다만 [[本:예전엔 혼자였고]], [[今:지금은 왠지 여럿이서 움직이고 있음]]."]}, "ISFP>ISTJ": {"karai": "성실하다는 말 듣지만, 그 성실함은 혼나기 싫은 마음으로 만들어져 있음.", "name": "꼼꼼한 척하는 기분파", "atari": ["[[今:서류는 기한 전에 완벽하게 내면서]], [[本:책상 위만큼은 좋아하는 소품으로 꽉 채워 놓음]].", "[[今:절차대로 진행하는 법을 익혔지만]], [[本:매번 속으로 '더 멋진 방법이 있는데' 하고 생각함]]."]}, "ISFP>ISFJ": {"karai": "눈치 빠르다는 말 듣지만, 눈치챈 걸 참고 쌓아두는 것도 특기가 됨.", "name": "준비성 좋아진 마이웨이", "atari": ["[[今:모두의 차 취향까지 기억하고 움직이면서]], [[本:내 일정은 훌쩍 바꾸고 싶어짐]].", "[[今:부탁받기 전에 미리 준비해 두게 됐지만]], [[本:그건 허둥대는 내 모습을 보기 싫어서임]]."]}, "ISFP>ESTJ": {"karai": "야무진 모습이 너무 몸에 배어서, 좋아하는 거 물어보면 순간 말문 막힘.", "name": "진행을 맡게 된 감성파", "atari": ["[[今:일정대로 안 되면 주의를 주면서]], [[本:내 휴일은 무계획이 제일 행복함]].", "[[今:딱 부러지게 지시를 내린 날 귀갓길]], [[本:'아까 말투 세지 않았나' 하고 폰을 꽉 쥐고 있음]]."]}, "ISFP>ESFJ": {"karai": "모두에게 너무 잘 맞춰줘서, 내 '좋아'가 어디론가 여행 떠나 있음.", "name": "총무로 뽑힌 자유인", "atari": ["[[今:다들 일정을 물어 가게를 예약해 놓고]], [[本:당일엔 예쁜 가게 내부 사진만 찍고 있음]].", "[[今:혼자 있는 사람을 그냥 못 두게 됐지만]], [[本:정작 내가 혼자 있고 싶은 날은 말을 못 꺼냄]]."]}, "ISFP>ISTP": {"karai": "건조한 척하지만, 받은 편지는 전부 상자에 넣어두고 못 버림.", "name": "쿨함을 익힌 감성파", "atari": ["[[今:감정을 안 드러내는 사람으로 보이지만]], [[本:좋아하는 곡 전주 1초 만에 울컥하고 있음]].", "[[今:상담을 받으면 논리로 답하게 됐지만]], [[本:사실은 \"알지\" 하면서 같이 우울해하고 싶음]]."]}, "ISFP>ISFP": {"karai": "화 안 내는 사람처럼 보여도, 마음속 '다시 안 볼 리스트'는 의외로 김.", "name": "좋아하는 걸 밀고 가는 마이웨이", "atari": ["유행보다 내 취향을 계속 고르다 보니, 어느새 방이 작은 미술관이 되어 있음.", "싫은 건 입 밖에 안 내지만, 얼굴이랑 발이 이미 그 자리를 뜨기 시작함."]}, "ISFP>ESTP": {"karai": "강한 척하지만, 살짝 차갑게 온 카톡을 세 번 다시 읽고 있음.", "name": "행동파가 된 섬세한 사람", "atari": ["[[今:기세로 뛰어들게 됐지만]], [[本:정하고 나서 '괜찮을까' 하고 혼자 술렁이고 있음]].", "[[今:그 자리 판단으로 진행할 수 있게 됐는데]], [[本:누가 슬픈 얼굴을 하면 금방 흔들림]]."]}, "ISFP>ESFP": {"karai": "밝은 캐릭터로 너무 굳어져서, 우울해도 \"잘 지내?\"라는 말밖에 안 들음.", "name": "사람들 앞에서 빛나는 숨은 내향인", "atari": ["[[今:파티에선 주인공급으로 신나 있으면서]], [[本:집에 오면 불도 안 켜고 이불로 직행함]].", "[[今:재밌는 건 전부 올라타지만]], [[本:진짜 즐거웠던 건 돌아오는 길에 혼자 들른 소품 가게임]]."]}, "INFP>INTJ": {"karai": "쿨하게 결론 내리는 중이지만, 그 결론엔 몰래 내 이상이 섞여 있음.", "name": "이상을 설계도로 만든 몽상가", "atari": ["[[今:합리적으로 계획을 세워 실행하고 있지만]], [[本:그 원동력은 누구에게도 말 못 할 커다란 꿈임]].", "[[今:남의 의견을 냉정하게 정리할 수 있게 됐는데]], [[本:영화 감동 장면에선 지금도 오열함]]."]}, "INFP>INTP": {"karai": "논리적인 척하는 건, 상처받지 않으려는 갑옷일 수 있음.", "name": "감정을 논리로 포장한 몽상가", "atari": ["[[今:좋아하는 작품 고찰을 논리적으로 써 내려가면서]], [[本:사실은 그냥 '존귀하다'고 말하고 싶을 뿐임]].", "[[今:고민 상담엔 분석으로 답하게 됐지만]], [[本:사실은 같이 울 준비도 되어 있음]]."]}, "INFP>ENTJ": {"karai": "강하게 진두지휘하지만, 사실 팀에서 제일 상처받기 쉬운 게 본인일 수 있음.", "name": "이상을 위해 앞에 선 몽상가", "atari": ["[[今:성과 내는 리더 노릇을 하면서]], [[本:머릿속에선 '이 일, 의미 있나?' 상영이 계속되는 중]].", "[[今:냉정한 판단을 내린 날 밤]], [[本:일기에 변명과 반성을 길게 쓰고 있음]]."]}, "INFP>ENTP": {"karai": "시니컬한 척하지만, 그건 로맨티스트인 걸 숨기려는 쑥스러움임.", "name": "받아칠 줄 알게 된 공상가", "atari": ["[[今:토론을 재밌어하게 됐지만]], [[本:심하게 말한 상대 마음을 한밤중에 몇 번이고 상상해 버림]].", "[[今:아이디어를 줄줄이 말하면서도]], [[本:진짜 소중한 꿈만큼은 아무한테도 말 안 함]]."]}, "INFP>INFJ": {"karai": "야무져 보이지만, 일정의 절반은 '제대로 사는 사람처럼 보이려고' 잡은 것.", "name": "준비성을 익힌 로맨티스트", "atari": ["[[今:사람 마음을 읽고 움직일 수 있게 됐지만]], [[本:내 마음의 일정만큼은 세우질 못함]].", "[[今:다이어리를 예쁘게 채우게 됐는데]], [[本:제일 즐거운 건 여백에 그리는 낙서임]]."]}, "INFP>INFP": {"karai": "이상이 너무 높아서, 현실의 약속은 대부분 \"다음에 보자\"로 끝냄.", "name": "영화관에 사는 몽상가", "atari": ["출근길 전철 15분 동안 주인공이 세 번 성장하는 장편을 머릿속에서 완결 지음.", "좋아하는 가사를 발견하면 그 한 줄로 하루 기분이 정해져 버림."]}, "INFP>ENFJ": {"karai": "기대받고 싶어서 열심히 하는데, 너무 기대받으면 갑자기 전부 도망치고 싶어짐.", "name": "모두의 마음을 지키는 공상가", "atari": ["[[今:무리의 분위기를 다듬는 역할이 됐지만]], [[本:집에 오면 내 마음 관리가 따라가질 못함]].", "[[今:남을 격려하는 말은 술술 나오는데]], [[本:나를 격려할 말은 하나도 안 떠오름]]."]}, "INFP>ENFP": {"karai": "사교적이 된 줄 알았는데, 약속 잡는 순간부터 '가기 싫다'도 같이 자라는 중.", "name": "밖으로 나온 몽상가", "atari": ["[[今:누구하고든 즐겁게 이야기할 수 있게 됐지만]], [[本:속마음을 털어놓을 상대는 아직도 두 명 정도]].", "[[今:설렌 일은 바로 사람들한테 말하게 됐지만]], [[本:제일 소중한 설렘은 아직 가슴속에 있음]]."]}, "INFP>ISTJ": {"karai": "견실한 사람을 연기하지만, 로또 당첨되면 짤 인생 계획만은 이상하리만치 디테일함.", "name": "현실에 착지한 몽상가", "atari": ["[[今:경비 정산을 꼼꼼히 끝낸 뒤]], [[本:책상 밑에서 몰래 소설 다음 전개를 생각하고 있음]].", "[[今:전례대로 일을 진행하면서]], [[本:속으로는 매일 '정말 이대로 괜찮을까' 묻고 있음]]."]}, "INFP>ISFJ": {"karai": "배려의 사람이란 말 듣지만, 거절 못 하고 떠맡은 일 때문에 내 꿈이 정체 중.", "name": "손을 움직이는 다정한 몽상가", "atari": ["[[今:모두가 좋아하는 과자를 기억해 챙겨 주지만]], [[本:사실은 내 세계에 빠질 시간이 필요함]].", "[[今:부탁받은 일을 묵묵히 해내면서]], [[本:머릿속에선 전혀 상관없는 이야기가 진행 중]]."]}, "INFP>ESTJ": {"karai": "믿음직한 상사처럼 보여도, 사실 엄하게 말한 자기 자신에게 제일 다운됨.", "name": "똑순이를 연기하는 몽상가", "atari": ["[[今:숫자와 기한으로 사람을 움직이면서]], [[本:속으로는 '다들 행복할까' 계속 신경 쓰고 있음]].", "[[今:일정표를 완벽하게 관리하는데]], [[本:문득 본 하늘색에 다 내던지고 싶어지는 날이 있음]]."]}, "INFP>ESFJ": {"karai": "남들이랑 같은 게 안심이라면서, 마음 깊은 곳에선 '특별한 누군가'가 되고 싶어 함.", "name": "모두의 자리를 만드는 공상가", "atari": ["[[今:회식 총무를 완벽하게 해내고]], [[本:돌아가는 전철에서 '오늘의 나, 괜찮았을까' 생각하고 있음]].", "[[今:남의 생일은 다 기억하면서]], [[本:내가 진짜 하고 싶은 건 아직 기억이 안 남]]."]}, "INFP>ISTP": {"karai": "쿨한 사람으로 통하지만, 옛날 실연은 아직도 머릿속에서 재상영 중.", "name": "쿨한 얼굴의 공상가", "atari": ["[[今:담담하게 작업을 해내게 됐지만]], [[本:손을 움직이는 동안 머릿속엔 계속 다른 이야기가 흐르고 있음]].", "[[今:감정을 겉으로 안 드러내는 만큼]], [[本:좋아하는 아티스트 얘기만 나오면 갑자기 말이 빨라짐]]."]}, "INFP>ISFP": {"karai": "지금을 즐기는 척은 늘었지만, 머리 반쪽은 아직 '만약의 세계'에 있음.", "name": "감각으로 사는 몽상가", "atari": ["[[今:좋아하는 걸 직감으로 고르게 됐지만]], [[本:고른 이유를 물으면 장대한 서사가 시작됨]].", "[[今:카페에서 사진 찍는 게 취미가 됐는데]], [[本:한 장 한 장에 멋대로 스토리를 붙이고 있음]]."]}, "INFP>ESTP": {"karai": "기세로 사는 것처럼 보여도, 사실 기세 없으면 이상이 너무 무거워서 못 움직임.", "name": "행동파로 변신한 몽상가", "atari": ["[[今:일단 움직여 보는 파가 됐지만]], [[本:움직인 뒤엔 혼자 의미를 붙이는 시간이 필요함]].", "[[今:분위기 따라 놀러 가게 됐는데]], [[本:즐거웠던 날 밤엔 왠지 조금 쓸쓸해짐]]."]}, "INFP>ESFP": {"karai": "재밌는 사람이란 말 들을 때마다 기쁘면서도, '나는 그런 사람이 아닌데' 하고 살짝 삐짐.", "name": "밝음을 장착한 몽상가", "atari": ["[[今:분위기 띄우는 게 특기가 됐지만]], [[本:귀갓길엔 좋아하는 곡을 반복 재생하며 나를 되찾고 있음]].", "[[今:패션도 이벤트도 전력으로 즐기면서]], [[本:마음속엔 아무에게도 안 보여 주는 노트가 있음]]."]}, "INTP>INTJ": {"karai": "결단이 빨라졌다고 생각하지만, 사실 생각하는 게 질린 순간 정하는 것뿐.", "name": "결론을 서두르게 된 탐구자", "atari": ["[[今:기한을 정해 결론을 내게 됐지만]], [[本:사실은 조사하는 도중이 제일 즐거움]].", "[[今:계획대로 진행하고 있는데]], [[本:한밤중에 상관없는 의문을 발견해서 세 시간 녹여 버림]]."]}, "INTP>INTP": {"karai": "머릿속으론 다 알고 있는데, 마감이랑 답장만은 영원히 미착수.", "name": "의문이 멈추지 않는 연구자", "atari": ["자기 전에 떠오른 '왜?'를 찾아보기 시작했다가, 정신 차려 보면 아침 새가 울고 있음.", "대화 중에 상대가 쓴 단어의 정의가 신경 쓰여서, 다음 이야기가 하나도 안 들어옴."]}, "INTP>ENTJ": {"karai": "리더답게 굴고 있지만, 스몰토크 시간만큼은 매번 어떻게 버틸지 모르겠음.", "name": "깃발을 든 연구자", "atari": ["[[今:팀을 이끌어 성과를 내면서도]], [[本:사실은 혼자 원인을 파고드는 작업을 하고 싶음]].", "[[今:회의에서 바로 결정할 수 있게 됐는데]], [[本:집에 와서 '그 판단의 근거'를 혼자 다시 검증하고 있음]]."]}, "INTP>ENTP": {"karai": "말 잘하게 된 줄 알았는데, 정신 차려보면 상대 얼굴 말고 내 논리를 보면서 말하고 있음.", "name": "말하는 검색 엔진", "atari": ["[[本:예전엔 알아낸 걸 조용히 가슴에 담아 뒀는데]], [[今:지금은 술자리에서 한 말씀 안 하고는 못 배김]].", "[[今:사람들과 토론하는 게 즐거워졌지만]], [[本:세 명 이상 모이면 갑자기 배터리가 닳기 시작함]]."]}, "INTP>INFJ": {"karai": "공감 잘하는 사람이 됐지만, 그 공감의 절반쯤은 관찰과 계산에서 나옴.", "name": "사람 마음까지 고찰하는 연구자", "atari": ["[[今:상대 마음을 읽게 됐지만]], [[本:읽은 결과를 머릿속에서 논문으로 정리하고 있음]].", "[[今:고민 상담에 다정하게 공감하면서]], [[本:마음 깊은 곳에선 '해결책 세 개 있는데' 하고 말하고 싶음]]."]}, "INTP>INFP": {"karai": "섬세해졌다고 하지만, 상처받은 이유부터 분석하기 시작하는 건 예전 그대로.", "name": "감정에 눈뜬 연구자", "atari": ["[[本:논리로 살아왔는데]], [[今:요즘은 좋아하는 작품 고찰글을 읽다가 울게 됨]].", "[[今:옳음보다 마음을 소중히 하고 싶다고 생각하면서도]], [[本:상대의 모순은 역시 눈에 들어옴]]."]}, "INTP>ENFJ": {"karai": "잘 챙겨주게 된 만큼, 내 호기심에 쓸 시간이 일주일에 30분밖에 안 남음.", "name": "사람을 이끌게 된 생각쟁이", "atari": ["[[今:후배 고민에 진심으로 공감해 줄 수 있게 됐지만]], [[本:집에 오면 말없이 퍼즐을 풀고 싶음]].", "[[今:모두의 의욕을 북돋는 말을 건네면서]], [[本:속으로는 그 말의 효과를 검증하고 있음]]."]}, "INTP>ENFP": {"karai": "흥으로 사는 척하지만, 그 흥엔 사전에 검증 세 단계가 끝나 있음.", "name": "설렘으로 움직이는 논리파", "atari": ["[[今:좋아하는 것에 들뜨게 됐지만]], [[本:들뜬 이유를 나중에 혼자 분석하고 있음]].", "[[今:새로운 만남을 즐길 수 있게 됐는데]], [[本:상대 이야기보다 말버릇의 법칙이 더 궁금함]]."]}, "INTP>ISTJ": {"karai": "현실파처럼 보여도, 전례대로 하는 건 생각하기 귀찮은 날뿐일 수 있음.", "name": "꼼꼼함을 장착한 탐구자", "atari": ["[[今:매뉴얼대로 일을 돌리면서]], [[本:'이 절차, 근본부터 다시 만들고 싶다' 하고 근질근질함]].", "[[今:매일 아침 같은 시간에 일어나게 됐지만]], [[本:자기 전 검색만큼은 아직도 규칙 밖임]]."]}, "INTP>ISFJ": {"karai": "착하다는 말 듣지만, 사실 남한테 맞춰주기보다 그냥 내버려 뒀으면 함.", "name": "배려 잘하는 생각쟁이", "atari": ["[[今:부탁에 웃으며 응하면서]], [[本:머릿속에선 '더 효율적인 방법 있는데' 하고 다시 설계하고 있음]].", "[[今:사람들 취향을 기억하게 됐지만]], [[本:그 기억 방식은 거의 데이터베이스임]]."]}, "INTP>ESTJ": {"karai": "야무진 사람을 연기하지만, 진짜 특기는 계획보다 '계획에 딴지 걸기'.", "name": "현장을 지휘하는 생각쟁이", "atari": ["[[今:일정을 관리하며 사람을 움직이지만]], [[本:휴일엔 하루 종일 잠옷 차림으로 논문을 읽고 싶음]].", "[[今:\"전례대로 하세요\"라고 지시하면서]], [[本:속으로는 그 전례의 허점을 세 개 찾아 둠]]."]}, "INTP>ESFJ": {"karai": "눈치가 늘었지만, 그건 분위기를 관찰 대상으로 연구한 성과임.", "name": "총무가 된 연구자", "atari": ["[[今:모두의 일정을 모아 가게를 예약하면서]], [[本:속으로는 최적의 날짜를 뽑는 방법을 궁리하고 있음]].", "[[今:누구하고든 밝게 이야기할 수 있게 됐지만]], [[本:진짜 즐거운 건 혼자 의문을 파고드는 시간임]]."]}, "INTP>ISTP": {"karai": "행동파가 된 줄 알았는데, 결국 설명서 주의사항까지 다 읽고 나서 만짐.", "name": "손도 쓰게 된 연구자", "atari": ["[[本:생각만 하던 사람이었는데]], [[今:지금은 궁금하면 분해해서 확인하는 파가 됨]].", "[[今:실전파가 됐다는 말을 듣지만]], [[本:작업 중에도 계속 '왜 이렇게 되지?'가 멈추지 않음]]."]}, "INTP>ISFP": {"karai": "느슨하게 사는 것처럼 보여도, 신경 쓰인 한마디는 사흘 내내 고찰 중.", "name": "감성으로 고르는 논리파", "atari": ["[[今:직감으로 좋아하는 걸 고를 수 있게 됐지만]], [[本:산 뒤에 비교표를 만들어서 스스로를 납득시키고 있음]].", "[[今:남의 마음에 공감하게 됐는데]], [[本:문득문득 상대 이야기의 모순이 신경 쓰임]]."]}, "INTP>ESTP": {"karai": "행동력 있다는 말 듣지만, 그건 생각만 하다 못 움직이던 과거에 대한 반동.", "name": "움직이기 시작한 검색 늪 주민", "atari": ["[[今:생각보다 먼저 움직이게 됐지만]], [[本:움직인 뒤의 반성회는 혼자 두 시간 걸림]].", "[[今:분위기 따라 놀이에 끼게 됐지만]], [[本:놀이 규칙의 허점을 찾는 게 제일 재밌음]]."]}, "INTP>ESFP": {"karai": "밝은 캐릭터는 완벽하지만, 그 대본은 집에서 혼자 연구해서 만든 것.", "name": "웃는 법을 배운 논리파", "atari": ["[[今:분위기 띄우는 역할이 됐지만]], [[本:빵 터진 개그의 이유를 귀갓길에 냉정하게 분석하고 있음]].", "[[今:유행에 올라타 즐길 수 있게 됐지만]], [[本:유행하는 원리가 더 궁금해져 버림]]."]}, "ESTP>INTJ": {"karai": "전략가처럼 조용히 있지만, 그 침묵의 절반은 '빨리 끝나라' 생각하는 시간.", "name": "계획서를 든 돌격대장", "atari": ["[[今:회의에선 \"장기적으로 보면\"이라고 말하면서]], [[本:사실은 지금 당장 현장으로 뛰어가고 싶어서 발이 근질근질함]].", "[[今:휴일 일정을 혼자 완벽하게 짜 놓고]], [[本:당일 아침 \"역시 바다 가자\"로 전부 뒤집고 싶어짐]]."]}, "ESTP>INTP": {"karai": "꼼꼼히 분석하는 척해놓고, 마지막엔 늘 '왠지 재밌어 보여서'로 정함.", "name": "생각이 너무 많은 행동파", "atari": ["[[今:새 가젯 비교 글을 세 시간 읽은 끝에]], [[本:결국 매장에서 만져 본 순간 사기로 결정함]].", "[[今:술자리 제안을 \"생각해 볼게\"로 보류하면서]], [[本:사실은 누구보다 먼저 도착하고 싶은 타입임]]."]}, "ESTP>ENTJ": {"karai": "냉철한 사령탑 얼굴을 해도, 승부욕이 얼굴에 드러나는 순간 다 들킴.", "name": "흥을 봉인한 사장 후보", "atari": ["[[今:부하 직원에겐 \"준비가 중요해\"라고 말하면서]], [[本:본인은 트러블이 터지는 순간이 제일 생기 넘침]].", "[[今:목표를 연 단위로 세우면서]], [[本:속으로는 '다음 주 일은 다음 주의 나한테 맡기고 싶다' 생각하고 있음]]."]}, "ESTP>ENTP": {"karai": "두뇌파인 척 말을 꺼내지만, 3분 뒤엔 '일단 해보자'로 착지함.", "name": "억지 논리도 되는 현장파", "atari": ["[[今:\"오히려 말이야\" 하고 토론을 시작해 놓고]], [[本:사실은 말하기 전에 해 보고 답을 내고 싶어 죽겠음]].", "[[今:아이디어를 열정적으로 이야기하는 도중에]], [[本:벌써 재료를 어디서 살지 궁리하고 있음]]."]}, "ESTP>INFJ": {"karai": "의미심장한 침묵을 만들 줄 알게 됐지만, 속은 대개 '배고프다'.", "name": "조용한 얼굴의 순발력", "atari": ["[[今:친구 상담에 깊이 끄덕여 주면서]], [[本:속으로는 '그래서 언제 움직일 건데?' 하며 운동화 끈을 묶고 있음]].", "[[今:남의 마음을 미리 읽고 신경 쓰는 나날이지만]], [[本:사실은 생각난 걸 그 자리에서 바로 말하고 싶음]]."]}, "ESTP>INFP": {"karai": "섬세한 캐릭터가 몸에 배어가는데, 말싸움 붙으면 누구보다 먼저 받아침.", "name": "꿈꾸는 스피드광", "atari": ["[[今:좋아하는 영화 세계에 빠져 있었는데]], [[本:정신 차려 보면 촬영지 가는 법을 찾아서 예약까지 끝냄]].", "[[今:남한테 상처 안 주려고 말을 고르지만]], [[本:속마음은 '그냥 확실히 말하는 게 빠르지 않나?']]."]}, "ESTP>ENFJ": {"karai": "모두를 위해 움직이는 얼굴이지만, 사실 제일 신난 건 본인임.", "name": "돌봄 담당 돌격대장", "atari": ["[[今:후배 고민을 진심으로 들어 주면서]], [[本:사실은 '한 번 해 보게 하면 알아' 하고 등을 떠밀고 싶어짐]].", "[[今:모두의 일정을 조율해서 여행을 짜 놓고]], [[本:정작 본인만 현지에서 계획에 없던 곳에 들르고 싶어서 근질근질함]]."]}, "ESTP>ENFP": {"karai": "감수성 풍부한 척하지만, 감동받은 영화 줄거리는 다음 날 이미 까먹음.", "name": "설렘 담당 실행범", "atari": ["[[今:\"뭔가 두근두근해!\" 하며 꿈을 이야기하지만]], [[本:그 꿈의 90%는 이미 신청 버튼을 눌러 둠]].", "[[今:친구 마음에 공감하는 말을 늘어놓으면서]], [[本:머릿속에선 해결책 세 개를 준비해 둠]]."]}, "ESTP>ISTJ": {"karai": "규칙 지키는 사람 얼굴을 하는 건, 어겼을 때가 더 귀찮다는 걸 알아서임.", "name": "매뉴얼을 지키는 승부사", "atari": ["[[今:매뉴얼대로 일을 진행하면서]], [[本:속으로는 '이 절차, 두 개는 건너뛸 수 있겠네' 하고 세고 있음]].", "[[今:저축 계획을 꼼꼼히 세운 그 주말에]], [[本:'한정 세일' 글자를 보고 이성이 순식간에 녹아내림]]."]}, "ESTP>ISFJ": {"karai": "조용한 착한 사람이고 싶은데, 칭찬받으면 두 배 속도로 다음 일 따러 감.", "name": "뒤로 물러난 관종", "atari": ["[[今:부탁받은 일을 묵묵히 해내면서]], [[本:사실은 \"봐 봐, 대단하지 않아?\"라고 말하고 싶어서 입이 근질근질함]].", "[[今:가족 일정에 맞춰 휴일을 양보해 놓고]], [[本:혼자만의 시간이 생기는 순간 드라이브하러 뛰쳐나감]]."]}, "ESTP>ESTJ": {"karai": "칼같은 척하지만, 일정표는 지키려고가 아니라 어기는 재미로 있는 것.", "name": "일정표를 든 야생아", "atari": ["[[今:팀에게 \"기한은 지키자\"라고 말하면서]], [[本:본인은 마감 전날 밤 벼락치기에 제일 불타오름]].", "[[今:여행 일정표를 만든 건 본인인데]], [[本:당일 일정표를 제일 무시하고 포장마차로 빨려 들어가고 있음]]."]}, "ESTP>ESFJ": {"karai": "누구에게나 다정한 사람으로 통하지만, 흥 없는 사람한텐 웃는 얼굴로 선 그음.", "name": "배려할 줄 아는 승부사", "atari": ["[[今:회식 총무로서 모두에게 신경 쓰면서도]], [[本:2차 노래방에선 누구보다 목청 높이고 싶은 속마음이 있음]].", "[[今:단톡방에선 이모티콘으로 정성껏 답하면서]], [[本:사실은 'ㅇㅋ' 두 글자로 끝내고 싶음]]."]}, "ESTP>ISTP": {"karai": "쿨한 독고다이처럼 굴지만, 안 불러주면 은근히 서운해하는 중.", "name": "낯가림이 생긴 행동파", "atari": ["[[今:혼자 묵묵히 자전거를 만지는 휴일에 만족하면서도]], [[本:누가 \"그거 대단하다\"라고 말해 주길 바라는 마음도 있음]].", "[[今:처음 보는 자리에선 조용히 있으면서]], [[本:친해지는 순간 누구보다 큰 소리로 웃고 있음]]."]}, "ESTP>ISFP": {"karai": "마이페이스 예술가인 척해도, 경쟁 붙으면 눈빛이 순식간에 바뀜.", "name": "감성으로 달리는 운동선수", "atari": ["[[今:좋아하는 옷을 혼자 고르는 시간을 즐기면서도]], [[本:사실은 입고 나간 곳에서 누가 봐 주길 바람]].", "[[今:남의 기분을 우선해서 말을 삼키지만]], [[本:귀갓길에 '말할걸' 하며 돌멩이를 차고 있음]]."]}, "ESTP>ESTP": {"karai": "행동력은 누구에게도 안 지지만, 뒷정리는 대개 주변 누군가가 하고 있음.", "name": "망설이기 전에 착지한 사람", "atari": ["궁금한 가게를 발견하면 검색보다 먼저 문을 열고 \"뭐가 제일 맛있어요?\"라고 묻고 있음.", "트러블이 생길수록 머리가 맑아져서, 다들 허둥대는 사이에 해결하고 벌써 다음 얘기 중."]}, "ESTP>ESFP": {"karai": "흥 많은 사람으로 통하는데, 손해 보는 얘기에만은 누구보다 냉정하게 안 넘어감.", "name": "분위기로 움직이는 순발력", "atari": ["[[今:분위기 띄우는 역할을 맡으면서]], [[本:속으로는 '이 기획, 더 효율적으로 돌릴 수 있는데' 생각하고 있음]].", "[[今:친구 연애 이야기에 온 힘으로 공감하면서]], [[本:\"그래서 고백은 언제 해?\" 하고 날짜를 정하게 하고 싶어짐]]."]}, "ESFP>INTJ": {"karai": "다 꿰뚫어 보는 척하면서, 재밌는 데 불려 가면 계획째로 내던짐.", "name": "쿨함을 걸친 축제 마니아", "atari": ["[[今:논리적으로 의견을 말한 뒤]], [[本:집에 와서 '말투 세지 않았나' 하고 혼자 반성회 중]].", "[[今:5년 후 계획을 세우는 진지한 얼굴 뒤에서]], [[本:사실은 오늘 밤 어디서 춤출지 생각하고 싶음]]."]}, "ESFP>INTP": {"karai": "논리적인 사람을 자처하지만, 결정타는 늘 '귀여워서' '재밌어 보여서'.", "name": "검색 늪에 빠진 축제단", "atari": ["[[今:궁금한 걸 혼자 파고들면서도]], [[本:재밌는 걸 발견하면 누구한테 말하고 싶어서 결국 전화하고 있음]].", "[[今:\"감정보다 논리\"라고 우기지만]], [[本:영화 엔딩 크레딧에선 누구보다 먼저 울고 있음]]."]}, "ESFP>ENTJ": {"karai": "유능한 리더 얼굴을 해도, 칭찬받고 싶은 마음만은 누구보다 솔직하게 얼굴에 드러남.", "name": "진행을 맡기 시작한 인기인", "atari": ["[[今:프로젝트를 숫자로 관리하면서]], [[本:사실은 멤버들과 뒤풀이에서 신나게 놀 날을 위해 버티는 중]].", "[[今:부하 직원에게 따끔하게 지적한 날 밤]], [[本:몰래 간식 선물을 고르고 있음]]."]}, "ESFP>ENTP": {"karai": "머리 회전 빠른 캐릭터로 통하지만, 논파한 뒤엔 미움받았을까 봐 계속 신경 씀.", "name": "토론도 되는 분위기 메이커", "atari": ["[[今:\"오히려 말이야\" 하고 논쟁을 걸지만]], [[本:사실은 상대랑 같이 웃으며 끝내고 싶어서 중간에 봐주고 있음]].", "[[今:새 아이디어를 마구 늘어놓으면서]], [[本:실제로는 눈앞의 재밌는 일로 머릿속이 꽉 차 있음]]."]}, "ESFP>INFJ": {"karai": "신비로운 사람처럼 보여도, 속은 꽤 단순해서 맛있는 거 있으면 기분 풀림.", "name": "생각에 잠긴 축제 마니아", "atari": ["[[今:사람 마음을 깊이 읽으려는 나날이지만]], [[本:사실은 복잡한 생각 없이 다 같이 웃고 싶음]].", "[[今:혼자만의 시간을 소중히 하기로 해 놓고]], [[本:주말 약속 제안이 오면 1초 만에 \"갈래!\"라고 답하고 있음]]."]}, "ESFP>INFP": {"karai": "내향적이 됐다지만, 신나는 자리에 던져지면 3분 만에 제일 시끄러워짐.", "name": "집에 틀어박힌 스포트라이트", "atari": ["[[今:방에서 혼자 망상 세계에 빠져 있을 줄 알았는데]], [[本:어느새 SNS에서 누군가의 반응을 기다리고 있음]].", "[[今:내 마음을 너무 챙기다 못 움직이는 날이 늘었지만]], [[本:사실은 느낀 대로 바로 움직이고 싶은 사람임]]."]}, "ESFP>ENFJ": {"karai": "훌륭한 선배를 연기하지만, 정작 내 내일 일정은 하나도 안 정해져 있음.", "name": "리더가 된 놀기 대장", "atari": ["[[今:모두의 성장을 생각하며 행사를 이끌면서]], [[本:본인은 그 행사의 장기자랑이 제일 기대됨]].", "[[今:친구 장래를 진지하게 이야기하면서도]], [[本:속으로는 '그것보다 이번 주 어디 갈래?' 생각하고 있음]]."]}, "ESFP>ENFP": {"karai": "가능성을 말하는 사람이 됐지만, 그 가능성의 내용은 대개 '재밌겠다' 한마디.", "name": "망상도 시작한 흥 담당", "atari": ["[[今:\"언젠가 세계 일주 하고 싶어\" 하며 거창한 꿈을 이야기하지만]], [[本:사실은 다음 주 고기 회식이 훨씬 더 기대됨]].", "[[今:새 취미에 설레서 장비를 다 갖춰 놓고]], [[本:써 보기도 전에 다른 설렘을 찾아냄]]."]}, "ESFP>ISTJ": {"karai": "알뜰한 현실파가 된 줄 알아도, '한정' '지금만' 글자엔 1밀리도 못 이김.", "name": "성실 모드에 들어간 장난꾸러기", "atari": ["[[今:매일 아침 같은 시간 전철을 타면서]], [[本:창밖의 모르는 역에 내려 보고 싶은 충동과 몰래 싸우는 중]].", "[[今:가계부를 꼼꼼히 쓰기 시작했지만]], [[本:영수증 절반은 '즐거웠으니 어쩔 수 없음' 지출임]]."]}, "ESFP>ISFJ": {"karai": "조용한 사람인 줄 알지만, 단체 사진에선 슬쩍 정중앙에 서 있음.", "name": "무대 뒤에 있는 주인공", "atari": ["[[今:회사 사람들 차를 말없이 준비하면서]], [[本:속으로는 '누가 알아채고 칭찬해 줘' 하고 작게 바라고 있음]].", "[[今:가족 일정을 우선하느라 내 약속을 미루고 있지만]], [[本:사실은 제일 먼저 놀러 나가고 싶음]]."]}, "ESFP>ESTJ": {"karai": "야무진 척해도, 신나는 약속 앞에선 그 일정표가 그냥 종이 쪼가리 됨.", "name": "규칙을 말하는 명랑한 사람", "atari": ["[[今:\"규칙은 규칙이니까\" 하고 주의를 준 뒤]], [[本:상대가 시무룩해 있으면 본인도 하루 종일 신경 쓰고 있음]].", "[[今:계획대로 일을 돌리면서]], [[本:사실은 예정에 없던 술자리에 불려 가는 순간을 기다리고 있음]]."]}, "ESFP>ESFJ": {"karai": "꼼꼼한 총무를 자처하지만, 회비 정산만은 매번 누군가한테 부탁함.", "name": "준비성 익힌 분위기 대장", "atari": ["[[今:생일 파티 준비를 완벽하게 계획해 놓고]], [[本:당일엔 서프라이즈 연출을 즉석에서 멋대로 추가하고 있음]].", "[[今:모임 일정 관리 담당이 됐지만]], [[本:사실은 불려 가서 올라타는 쪽이 더 재밌음]]."]}, "ESFP>ISTP": {"karai": "건조한 성격이 됐다고 우기지만, 아기 고양이 영상 하나에 그 설정 무너짐.", "name": "말없이 만드는 무드메이커", "atari": ["[[今:혼자 묵묵히 DIY에 몰두하는 휴일인데]], [[本:완성하면 바로 사진 찍어서 친구들한테 보내고 있음]].", "[[今:감정 안 드러내는 쿨한 대응을 익혔지만]], [[本:속으로는 상대 반응 하나하나에 일희일비하고 있음]]."]}, "ESFP>ISFP": {"karai": "사람 많은 데 싫다면서, 페스티벌 티켓만은 선예매로 야무지게 잡아둠.", "name": "혼자가 좋아진 인기인", "atari": ["[[今:좋아하는 카페에서 혼자만의 시간을 즐길 생각이었는데]], [[本:직원이랑 친해져서 어느새 단골이 되어 있음]].", "[[今:여럿 모이는 자리를 피하게 됐는데]], [[本:소수끼리면 누구보다 이야기를 띄우고 있음]]."]}, "ESFP>ESTP": {"karai": "쿨한 스타일을 자처하지만, 읽씹당하면 밤까지 이유 고민함.", "name": "승부욕 생긴 무드메이커", "atari": ["[[今:승부에선 강하게 밀어붙이면서]], [[本:진 상대가 풀 죽어 있으면 저도 모르게 위로하러 가 있음]].", "[[今:\"손익으로 생각하자\"라고 말하면서]], [[本:결국 같이 있으면 즐거운 사람 부탁을 먼저 들어줌]]."]}, "ESFP>ESFP": {"karai": "지금을 즐기는 천재지만, 그 '지금'의 청구서는 미래의 내가 전부 냄.", "name": "타고난 축제 체질", "atari": ["재밌어 보이는 약속엔 내용도 듣기 전에 \"갈래!\"라고 답해서, 일정이 늘 세 개씩 겹쳐 있음.", "그 자리 모두를 웃기는 데 온 힘을 쏟다가, 귀갓길에야 겨우 내가 지친 걸 알아챔."]}, "ENFP>INTJ": {"karai": "논리파를 연기하는데, 정한 이유 물으면 \"뭔가, 운명 같았어\".", "name": "설렘을 봉인한 참모", "atari": ["[[今:효율 중심으로 스케줄을 짜면서]], [[本:문득 본 포스터 한 장에 일정 전체를 다시 짜고 싶어짐]].", "[[今:냉정하게 바른 말을 할 수 있게 됐지만]], [[本:속으로는 상대 기분을 계속 신경 쓰고 있음]]."]}, "ENFP>INTP": {"karai": "감정보다 논리라면서, 그 논리는 좋아하는 걸 정당화할 때만 빛남.", "name": "검색 늪에서 사랑에 빠진 사람", "atari": ["[[今:좋아하게 된 걸 혼자 철저하게 파고들다가]], [[本:어느새 누구보다 빠삭해져서 말하고 싶어 죽겠음]].", "[[今:사람 만나는 걸 귀찮아하면서]], [[本:말 통하는 사람을 찾는 순간 아침까지 이야기가 안 멈춤]]."]}, "ENFP>ENTJ": {"karai": "스토익한 진행 담당 얼굴이지만, 계획표 여백엔 다음에 하고 싶은 것 낙서가 있음.", "name": "꿈을 숫자로 바꾼 사령탑", "atari": ["[[今:목표와 기한을 정해 팀을 이끌지만]], [[本:사실은 다 같이 '재밌겠다'만으로 달려 나가고 싶음]].", "[[今:따끔한 피드백을 보낸 뒤]], [[本:카톡 답장이 올 때까지 폰을 몇 번이나 들여다보고 있음]]."]}, "ENFP>ENTP": {"karai": "매운맛 캐릭터 시작했지만, 내 기획에 반대당하면 누구보다 티 나게 시무룩해짐.", "name": "논리로 무장한 로맨티스트", "atari": ["[[今:\"그거 근거 있어?\" 하고 따지는 쪽이 됐는데]], [[本:내 기획의 근거는 '딱 감이 왔음'뿐임]].", "[[今:아이디어 내는 건 잘하지만]], [[本:사실은 논리보다 '왠지 좋아'라는 마음으로 고르고 싶음]]."]}, "ENFP>INFJ": {"karai": "차분한 사람이란 말 듣지만, 최애 새 소식 뜬 밤만큼은 누구보다 시끄러움.", "name": "듣는 쪽이 된 수다쟁이", "atari": ["[[今:듣는 역할에 충실하며 상대 속마음을 읽지만]], [[本:사실은 내 설렘 얘기를 세 시간 떠들고 싶음]].", "[[今:미래 계획을 노트에 정리하는 게 일과가 됐지만]], [[本:페이지마다 꿈 내용이 바뀌어 있음]]."]}, "ENFP>INFP": {"karai": "내향형을 자처하지만, 잘 맞는 사람 앞에선 누구보다 떠들어서 상대를 지치게 함.", "name": "1인 상영회의 홍보 담당", "atari": ["[[今:머릿속 이야기에 혼자 빠지는 게 좋아졌지만]], [[本:사실은 누군가와 이야기를 나눠야 완성되는 사람임]].", "[[今:사람 만나는 약속에 지쳐서 집에 틀어박히면서도]], [[本:틀어박힌 지 사흘 만에 괜히 누군가 보고 싶어짐]]."]}, "ENFP>ENFJ": {"karai": "야무진 얼굴을 하고 있지만, 내 방 정리는 3년째 '언젠가' 상태.", "name": "책임감을 짊어진 자유인", "atari": ["[[今:모두를 챙기며 이벤트를 이끌지만]], [[本:사실은 내가 즉흥으로 놀러 가고 싶은 쪽임]].", "[[今:후배 상담해 줄 땐 듬직한데]], [[本:내 고민은 아무한테도 말 안 하고 끌어안고 있곤 함]]."]}, "ENFP>ENFP": {"karai": "시작하는 힘은 천하제일인데, 중간에 멈춘 취미 장비로 붙박이장이 터져 나감.", "name": "설렘에 너무 솔직한 사람", "atari": ["새 만남이나 취미에 금방 빠져서, 사진첩이 한 달마다 다른 사람 폴더가 되어 있음.", "남의 장점을 찾는 천재라서, 처음 본 사람한테도 30분 만에 \"운명인가 봐\"라고 말하고 있음."]}, "ENFP>ISTJ": {"karai": "꼼꼼한 사람으로 통하지만, 다이어리 내용은 일정보다 망상이 더 많음.", "name": "매뉴얼을 지키는 공상가", "atari": ["[[今:정해진 절차를 지키며 일을 해내면서]], [[本:머릿속에선 전혀 다른 기획이 열 개쯤 부풀고 있음]].", "[[今:매일 같은 루틴을 지키는 나에게 안심하면서도]], [[本:마음 깊은 곳에선 '이대로 괜찮나?' 하고 술렁이고 있음]]."]}, "ENFP>ISFJ": {"karai": "조용하고 성실해 보이는데, 좋아하는 얘기만 나오면 갑자기 속사포로 안 멈춤.", "name": "착실 모드의 여행자", "atari": ["[[今:부탁받은 일을 정성껏 해내면서]], [[本:사실은 '이렇게 하면 더 재밌을 텐데' 하고 말하고 싶어서 근질근질함]].", "[[今:가족이나 친구 일정을 우선하고 있지만]], [[本:속으로는 혼자 먼 도시로 떠나는 상상을 하고 있음]]."]}, "ENFP>ESTJ": {"karai": "남의 진척 상황은 철저히 관리하면서, 내 꿈의 마감만은 계속 미루는 중.", "name": "일정표에 꿈을 적는 사람", "atari": ["[[今:팀 진행 순서를 꼼꼼히 정하면서]], [[本:사실은 더 엉뚱한 아이디어를 시험해 보고 싶음]].", "[[今:\"현실적으로 생각하면\"이 입버릇이 됐지만]], [[本:자기 전엔 거대한 꿈의 다음 편을 망상하고 있음]]."]}, "ENFP>ESFJ": {"karai": "상식적인 정리 담당처럼 보여도, 2차부터는 정리할 생각이 1도 없어짐.", "name": "총무가 된 꿈꾸는 사람", "atari": ["[[今:회식 장소 고르기부터 계산까지 완벽하게 해내지만]], [[本:사실은 목적지 미정 여행에 누군가를 꼬시고 싶음]].", "[[今:모두의 의견을 모아 분위기를 둥글게 정리하면서]], [[本:속으로는 '더 이상한 아이디어도 괜찮은데' 생각하고 있음]]."]}, "ENFP>ISTP": {"karai": "과묵하고 쿨한 캐릭터가 됐지만, 속으로 하는 혼잣말은 누구보다 시끄러움.", "name": "과묵한 척하는 수다 뇌", "atari": ["[[今:감정 안 드러내는 담담한 대응이 몸에 뱄지만]], [[本:속으로는 상대 말 한마디에 하루 종일 휘둘리고 있음]].", "[[今:혼자 손 쓰는 작업에 몰두하면서]], [[本:어느새 만든 물건에 이름 붙여서 말을 걸고 있음]]."]}, "ENFP>ISFP": {"karai": "마이페이스 자유인을 자처하는 것치고, 아무 연락 없는 휴일엔 의외로 약함.", "name": "혼자만의 시간을 알게 된 사교가", "atari": ["[[今:혼자 좋아하는 음악이나 옷을 즐기는 시간이 늘었지만]], [[本:좋은 걸 발견하면 누군가에게 보여 주지 않고는 못 배김]].", "[[今:'지금을 느끼며 살자'고 다짐해 놓고]], [[本:정신 차려 보면 10년 뒤 망상으로 한 시간이 지나 있음]]."]}, "ENFP>ESTP": {"karai": "시원시원한 행동파인 척하지만, 칭찬받으면 티 나게 들뜸.", "name": "현실주의를 시작한 꿈쟁이", "atari": ["[[今:\"일단 움직이자\" 하고 바로 결정하게 됐지만]], [[本:정한 뒤에 '그 사람은 어떻게 생각했을까' 되돌아보고 있음]].", "[[今:눈앞의 승부나 손익엔 강해졌는데]], [[本:사실은 의미와 낭만이 있는 도전이어야 불타는 사람임]]."]}, "ENFP>ESFP": {"karai": "흥 많은 사람으로 통하지만, 그 흥의 의미를 혼자 과몰입 해석하다 알아서 지침.", "name": "지금을 즐기는 미래 망상가", "atari": ["[[今:눈앞의 이벤트를 온 힘으로 즐기면서]], [[本:귀갓길엔 벌써 '다음엔 이렇게 하고 싶다' 하고 기획을 짜고 있음]].", "[[今:유행하는 가게를 도는 나날이지만]], [[本:사실은 아직 아무도 모르는 곳을 찾아내고 싶은 사람임]]."]}, "ENTP>INTJ": {"karai": "냉철한 전략가처럼 보여도, 사실 누가 반박해 주길 바라서 일부러 빈틈 만드는 중.", "name": "계획을 세운 청개구리", "atari": ["[[今:치밀한 계획을 혼자 다듬어 완성해 놓고]], [[本:완성되는 순간 '오히려 이걸 부수면?' 하는 생각이 떠올라 버림]].", "[[今:회의에서 조용히 듣고 있는 것 같아도]], [[本:속으로는 모두의 의견에 하나하나 태클을 걸고 있음]]."]}, "ENTP>INTP": {"karai": "조용한 논리파를 자처하지만, 말상대 없으면 혼잣말로 토론 시작함.", "name": "반론을 마음에 담아 두는 사람", "atari": ["[[今:혼자 생각에 잠기는 시간이 늘었지만]], [[本:좋은 논리가 떠오르면 누구한테 던지고 싶어서 못 참음]].", "[[今:SNS 논쟁을 조용히 지켜보면서]], [[本:머릿속에선 장문의 반론을 이미 세 편 써 둠]]."]}, "ENTP>ENTJ": {"karai": "결단력 있다는 말 듣지만, 그 결단은 전날 떠오른 제일 재밌는 안일 수 있음.", "name": "진행 담당 트릭스터", "atari": ["[[今:목표와 기한을 정해 팀을 움직이면서]], [[本:사실은 중간에 방침을 뒤집는 순간이 제일 즐거움]].", "[[今:효율적인 회의를 진행하면서도]], [[本:잡담이 옆길로 새기 시작하면 말리긴커녕 제일 신나 있음]]."]}, "ENTP>ENTP": {"karai": "아이디어 샘물인데, 실행 단계가 되면 갑자기 다른 아이디어 샘물로 이사 가 있음.", "name": "반론이 취미인 발명가", "atari": ["누가 \"그건 무리지\"라고 하는 순간, 오히려 해야 할 이유를 열 개 떠올리고 있음.", "진심으로 찬성하는 이야기인데도, 괜히 반대편에 서 보고 싶어서 논쟁을 걸고 있음."]}, "ENTP>INFJ": {"karai": "사려 깊어 보이는 그 침묵은, 반박을 모나지 않게 말할 방법을 짜는 시간.", "name": "다정함을 배운 논객", "atari": ["[[今:상대 마음을 읽고 말을 고르지만]], [[本:속으로는 '근데 그거 앞뒤가 안 맞지 않아?' 생각하고 있음]].", "[[今:조용히 듣는 역할을 하다가도]], [[本:토론이 달아오르면 못 참고 몸을 앞으로 내밀고 있음]]."]}, "ENTP>INFP": {"karai": "섬세한 사람을 자처하지만, 말싸움에서 진 날만은 밤새 꽁해 있음.", "name": "시인인 척하는 논파왕", "atari": ["[[今:좋아하는 작품 세계관을 혼자 음미하면서]], [[本:어느새 설정 모순을 노트에 정리하고 있음]].", "[[今:남한테 상처 주기 싫어서 의견을 삼키지만]], [[本:집에 와서 욕조 안에서 완벽한 반론을 연습하고 있음]]."]}, "ENTP>ENFJ": {"karai": "착한 사람 포지션에 자리 잡았지만, 가끔 나오는 독설이 진짜 본캐 매력.", "name": "잘 챙겨 주는 장난꾸러기", "atari": ["[[今:후배 고민에 공감하며 격려하지만]], [[本:사실은 '그 고민, 전제부터 의심해 보면?' 하고 말하고 싶음]].", "[[今:모두가 즐길 수 있게 순서를 짜면서]], [[本:몰래 예상 밖의 장치를 하나 넣어 둠]]."]}, "ENTP>ENFP": {"karai": "감정 풍부한 사람으로 통하지만, 눈물 나는 영화 보고 나온 소감이 대개 '각본 잘 썼네'.", "name": "공감 잘하는 억지 논리왕", "atari": ["[[今:친구 이야기에 \"완전 알지~!\" 하고 공감하면서]], [[本:머리 한구석에선 이야기의 모순을 냉정하게 세고 있음]].", "[[今:설렘으로 움직이는 것처럼 보여도]], [[本:사실은 재미를 논리로 계산한 다음 뛰어들고 있음]]."]}, "ENTP>ISTJ": {"karai": "성실하고 견실한 사람 탈을 쓰고, 머릿속에선 늘 개혁안 짜는 중.", "name": "매뉴얼을 의심하는 모범생", "atari": ["[[今:규칙대로 꼼꼼히 일을 진행하면서]], [[本:사실은 '이 규칙 누가 정했어요?'라고 묻고 싶어 죽겠음]].", "[[今:매일 같은 절차를 지키는 안정감을 알게 됐지만]], [[本:가끔 이유 없이 귀갓길을 바꿔서 작게 반항하고 있음]]."]}, "ENTP>ISFJ": {"karai": "배려왕처럼 보여도, 그 배려 절차마저 효율화하고 싶어서 근질근질함.", "name": "얌전해진 반항아", "atari": ["[[今:부탁받은 일을 말없이 맡으면서]], [[本:속으로는 '더 편한 방법 있는데' 하고 세 가지 안을 떠올리고 있음]].", "[[今:주변에 맞춰 얌전히 있지만]], [[本:사실은 회의에서 제일 먼저 \"오히려 말이야\"라고 말하고 싶음]]."]}, "ENTP>ESTJ": {"karai": "규칙에 엄한 사람을 연기하지만, 나한테 불리한 규칙엔 날카로운 핑계를 준비해 둠.", "name": "전례를 지키는 개혁파", "atari": ["[[今:\"전례대로 갑시다\" 하고 회의를 정리하면서]], [[本:사실은 전례를 깨는 제안을 제일 하고 싶은 사람임]].", "[[今:업무 관리 앱을 능숙하게 쓰면서]], [[本:새 앱이 나올 때마다 갈아타고 있음]]."]}, "ENTP>ESFJ": {"karai": "모두의 편으로 통하지만, 속으론 전원 발언에 몰래 점수 매기는 중.", "name": "눈치 보는 독설가", "atari": ["[[今:모두의 의견에 웃으며 끄덕이는 총무를 하면서]], [[本:속으로는 제일 꼬인 태클을 꾹 참고 있음]].", "[[今:주변 기분에 맞춰 의견을 바꾸지만]], [[本:집에 오면 '아까 그거 논리가 이상했어' 하고 검증하고 있음]]."]}, "ENTP>ISTP": {"karai": "과묵한 장인처럼 보여도, 태클 걸 거리 찾은 순간만 갑자기 말이 많아짐.", "name": "말없이 시험하는 논리파", "atari": ["[[今:토론보다 손을 움직이게 됐지만]], [[本:작업하면서 머릿속으로 계속 나 자신과 토론 중]].", "[[今:기계나 도구를 분해해서 구조를 확인하면서]], [[本:'이거 더 재밌게 개조할 수 있겠다' 하고 망상이 멈추지 않음]]."]}, "ENTP>ISFP": {"karai": "느긋한 사람처럼 보여도, 입 열면 온화한 얼굴 그대로 핵심을 찌름.", "name": "온화한 시니컬쟁이", "atari": ["[[今:좋아하는 걸 감각으로 고르는 생활을 즐기면서]], [[本:고른 이유를 물으면 갑자기 이론으로 설명하기 시작함]].", "[[今:남과 다투지 않게 온화하게 지내지만]], [[本:사실은 한 번쯤 진심으로 논쟁을 걸어 보고 싶음]]."]}, "ENTP>ESTP": {"karai": "행동파로 보이지만, 질리는 속도만은 예나 지금이나 누구에게도 안 짐.", "name": "생각보다 시험이 먼저인 논객", "atari": ["[[今:논리를 따지기 전에 먼저 해 보게 됐지만]], [[本:잘되고 나면 이유를 30분 동안 설명하고 있음]].", "[[今:분위기로 정한 척하면서]], [[本:사실은 머릿속에서 다섯 가지 전개를 시뮬레이션해 둠]]."]}, "ENTP>ESFP": {"karai": "태평한 캐릭터로 통하지만, 재미없는 얘기엔 영혼 없는 웃음조차 안 나옴.", "name": "흥으로 감춘 전략가", "atari": ["[[今:다 같이 신나게 놀고 있으면서]], [[本:문득 \"이 놀이, 규칙 바꾸면 더 재밌지 않아?\"라고 말을 꺼냄]].", "[[今:재미 우선으로 움직이는 것처럼 보여도]], [[本:누구랑 짝지어야 제일 재밌어질지 냉정하게 읽고 있음]]."]}, "ESTJ>INTJ": {"karai": "남한테 맡기느니 내가 하는 게 빠르단 걸 깨닫고, 아무한테도 안 기대게 된 것뿐일 수 있음.", "name": "말없이 지휘하는 현장 감독", "atari": ["[[今:회의에선 조용히 듣고 있으면서]], [[本:귀갓길엔 모두의 역할 분담을 머릿속에서 다시 짜고 있음]].", "[[本:예전 같으면 구령을 붙였을 상황에서도]], [[今:지금은 자료만 완벽하게 준비해 놓고 뒷자리에 앉아 있음]]."]}, "ESTJ>INTP": {"karai": "자유인처럼 굴지만, 약속에 늦는 사람한텐 예전 그대로 칼같이 화냄.", "name": "일정표를 버린 전직 진행왕", "atari": ["[[本:계획 짜고 싶어 하는 사람일 텐데]], [[今:지금은 '애초에 이거 필요해?' 하고 찾아보다 하루가 저묾]].", "[[今:총무 부탁은 거절하면서]], [[本:가게 비교표만큼은 왠지 누구보다 꼼꼼하게 만들어 둠]]."]}, "ESTJ>ENTJ": {"karai": "새로운 제안하는 건 좋아하면서, 남의 새 제안엔 일단 \"전례는?\"부터 물음.", "name": "현장도 비전도 지휘하는 사람", "atari": ["[[今:큰 꿈을 이야기하면서]], [[本:정신 차려 보면 손 밑 메모에 날짜랑 담당자 이름을 빽빽하게 적고 있음]].", "[[今:\"전례가 없으니까 더 해 보자\"라고 말하는 지금의 나에게]], [[本:예전의 내가 제일 놀라고 있음]]."]}, "ESTJ>ENTP": {"karai": "틀을 깨는 사람을 자처하지만, 내가 정한 틀을 남이 깨면 꽤 언짢아함.", "name": "규칙을 깨고 싶은 선도부", "atari": ["[[今:회의에서 \"오히려 말이야\"를 꺼내 놓고]], [[本:결정되는 순간부터 누구보다 성실하게 진행 상황을 관리하고 있음]].", "[[本:규칙을 지키게 하는 쪽이었는데]], [[今:지금은 빠져나갈 구멍을 찾으면 묘하게 신이 남]]."]}, "ESTJ>INFJ": {"karai": "다정하게 들어주는 역할이지만, 같은 고민 상담 세 번째부턴 속으로 회의록 쓰기 시작함.", "name": "눈치가 너무 빠른 호랑이 교관", "atari": ["[[今:후배 고민을 말없이 끄덕이며 들으면서]], [[本:속으로는 해결까지의 절차를 세 단계로 나누고 있음]].", "[[本:흑백을 확실히 가리고 싶은 성격인데]], [[今:지금은 상대 눈치를 보며 결론을 다음 주로 미루고 있음]]."]}, "ESTJ>INFP": {"karai": "섬세한 나를 소중히 하지만, 남의 핑계엔 예전의 엄격함이 그대로 튀어나옴.", "name": "꿈꾸는 계획 대장", "atari": ["[[今:휴일엔 좋아하는 이야기 세계에 빠져 있으면서]], [[本:월요일 아침이 되면 계획의 화신이 갑자기 깨어남]].", "[[本:'말한 건 한다'가 신조였는데]], [[今:지금은 의욕 안 나는 날의 나도 봐주는 연습 중]]."]}, "ESTJ>ENFJ": {"karai": "잘 챙겨준다고 소문났지만, 말 안 듣는 사람은 꽤 빨리 안 챙기게 됨.", "name": "다정하게 몰아붙이는 돌봄 담당", "atari": ["[[今:\"괜찮아? 무리하지 마\"라고 말한 직후에]], [[本:그 사람 마감일을 확실히 확인하고 있음]].", "부하 직원 보고를 들을 때 [[今:숫자보다 \"고생했어\"가 먼저 나오는]] 나에게 가끔 놀람."]}, "ESTJ>ENFP": {"karai": "자유로운 사람으로 보이고 싶어 노력하지만, 일정이 세 번 바뀌면 정색함.", "name": "신난 척하는 관리자", "atari": ["[[今:즉흥으로 여행을 정한 것처럼 보여 놓고]], [[本:출발 전엔 준비물 리스트랑 집합 시간을 모두에게 보내 둠]].", "[[本:계획대로 하고 싶은 본심을 누르고]], [[今:지금은 즉흥에 올라타는 나를 즐겨 보려는 중]]."]}, "ESTJ>ISTJ": {"karai": "조용한 척하지만, 진행 허술한 사람 보면 속으로 전부 다시 하고 있음.", "name": "구령 안 붙이는 반장", "atari": ["[[本:모두를 이끌고 싶은 속마음은 접어 두고]], [[今:지금은 내 담당만 완벽하게 해 놓고 정시에 조용히 퇴근함]].", "단톡방에서 아무도 안 정할 때 [[今:읽씹 상태로 버티다가]] [[本:결국 한밤중에 일정안을 투척함]]."]}, "ESTJ>ISFJ": {"karai": "헌신하는 것처럼 보여도, 상대가 내 방식대로 움직일 때까지 헌신을 멈추지 않음.", "name": "부탁도 잘 들어주는 진행왕", "atari": ["[[今:부탁받은 일을 웃으며 맡으면서]], [[本:머릿속에선 '처음부터 말해 주지' 하며 순서를 다시 짜고 있음]].", "[[本:'이렇게 해야 해'라고 말하고 싶은 걸]], [[今:지금은 상대가 상처 안 받을 말투를 세 번 생각하고 나서 말함]]."]}, "ESTJ>ESTJ": {"karai": "\"보통 이렇잖아\"의 '보통'이 대개 내 규칙이라는 걸 모름.", "name": "타고난 일정표 마스터", "atari": ["여행 얘기가 나오는 순간 표를 만들고, 누구보다 먼저 숙소랑 집합 시간을 정해서 공유함.", "말한 건 반드시 하고, 안 하는 사람도 반드시 기억함. 겉과 속이 같은 게 자랑임."]}, "ESTJ>ESFJ": {"karai": "모두의 의견이 소중하다지만, 결국 처음 낸 내 제안으로 확실히 결정됨.", "name": "웃으며 이끄는 반장", "atari": ["[[本:\"그건 아니야\"라고 말하기 전에]] [[今:\"좋다!\"를 하나 끼워 넣지 않으면 말을 못 하는 몸이 됨]].", "[[今:회식 총무로 모두의 호불호를 물으면서]], [[本:속으로는 예산과 시간을 초 단위로 계산하고 있음]]."]}, "ESTJ>ISTP": {"karai": "마이페이스인 척하지만, 내 페이스 흐트러지면 누구보다 디테일하게 불평함.", "name": "계획 안 세우는 장인", "atari": ["[[本:계획부터 세우고 움직이던 사람인데]], [[今:지금은 설명서 읽기 전에 일단 손부터 움직이고 있음]].", "[[今:휴일엔 아무도 안 만나고 방 수리를 하다가]], [[本:왠지 평일 업무 개선안이 떠오르고 있음]]."]}, "ESTJ>ISFP": {"karai": "딱히 고집 없는 척하지만, 분리수거 틀리는 사람한텐 지금도 확실히 엄격함.", "name": "마음대로 살고 싶은 전직 반장", "atari": ["[[本:원칙을 지키고 싶은 성격일 텐데]], [[今:지금은 '좋아서'라는 이유만으로 옷도 일도 고르려 하고 있음]].", "[[今:느슨하게 살기로 정한 날부터]], [[本:왠지 '느슨하게 살기 위한 계획'을 세우기 시작함]]."]}, "ESTJ>ESTP": {"karai": "임기응변이 장점이라면서, 남이 즉석에서 일정 바꾸면 \"못 들었는데?\" 하기 일쑤.", "name": "달리면서 지휘하는 사람", "atari": ["[[今:일단 움직이고 나서 생각하게 됐는데]], [[本:끝난 뒤 반성회만큼은 빼먹지 않음]].", "[[今:그 자리 분위기로 정한 일정이 더 잘 풀린다는 걸 알고 나서]] 다이어리 빈칸이 조금 늘었음."]}, "ESTJ>ESFP": {"karai": "재밌으면 그만이라면서, 재미없게 진행되면 진심으로 지적질 들어감.", "name": "흥으로 띄우는 감독", "atari": ["[[今:회식에선 누구보다 분위기 메이커인데]], [[本:귀가 택시 배정만큼은 확실하게 정해 둠]].", "[[本:결과가 전부였던 사람이]] [[今:지금은 '즐거웠으니 됐다'로 하루를 마무리할 수 있게 됨]]."]}, "ESFJ>INTJ": {"karai": "감정으로 안 움직인다고 우기지만, 생일 잊힌 날은 하루 종일 꽁해 있음.", "name": "쿨한 척하는 총무", "atari": ["[[今:합리적으로 약속을 거절한 것처럼 보여 놓고]], [[本:거절한 상대를 밤까지 계속 신경 쓰고 있음]].", "[[今:'혼자 하는 게 빠르다'가 입버릇이면서]], [[本:팀 간식만큼은 매번 본인이 나눠 주고 있음]]."]}, "ESFJ>INTP": {"karai": "건조한 척하지만, 누가 의지하는 순간 목소리 톤 한 단계 올라가는 거 못 숨김.", "name": "논리 뒤에 숨은 인기인", "atari": ["[[本:누군가에게 도움이 되고 싶은 본심보다]] [[今:지금은 '그게 무슨 의미가 있지?'가 먼저 떠오름]].", "[[今:혼자 조사에 몰두하고 있다가도]], [[本:친구한테 상담 카톡이 오면 1초 만에 답장해 버림]]."]}, "ESFJ>ENTJ": {"karai": "단호하게 정하는 줄 알아도, 반대 의견 나오면 일단 \"화난 거 아니지?\"부터 확인함.", "name": "정 많은 원맨 사장", "atari": ["[[今:엄하게 지시를 내린 뒤]], [[本:몰래 간식을 두고 수습하는 나를 못 끊음]].", "[[本:모두에게 사랑받고 싶은 게 본심인데]], [[今:지금은 미움받는 역할을 맡아서라도 결과를 따내러 감]]."]}, "ESFJ>ENTP": {"karai": "논파 캐릭터를 즐기지만, 진짜 말로 이긴 상대한텐 나중에 사과 이모티콘 보냄.", "name": "태클 담당 총무", "atari": ["[[今:\"오히려 말이야\" 하고 토론을 휘저으면서]], [[本:분위기가 싸해지는 순간 허둥지둥 모두를 칭찬하기 시작함]].", "[[本:늘 가던 가게, 늘 보던 멤버로 안착할 줄 알았는데]], [[今:지금은 \"새로운 거 해 보자\"고 말을 꺼내는 쪽에 있음]]."]}, "ESFJ>INFJ": {"karai": "조용한 사람을 연기하지만, 나 빼고 불타는 단톡방엔 마음이 술렁임.", "name": "혼자서 챙기는 총무", "atari": ["[[今:대규모 회식은 거절하면서]], [[本:못 온 사람한테 줄 선물만큼은 꼭 챙겨 둠]].", "[[本:모두의 한가운데 있고 싶은 사람인데]], [[今:지금은 조금 떨어진 곳에서 모두의 표정을 지켜보고 있음]]."]}, "ESFJ>INFP": {"karai": "혼자가 좋다면서, 누가 \"요즘 어때?\" 물어봐 주길 계속 기다리는 중.", "name": "방에 틀어박힌 오지랖", "atari": ["[[今:집에서 혼자 이야기 세계에 빠져 있으면서도]], [[本:친구 생일만큼은 캘린더에 전부 넣어 둠]].", "[[今:한밤중에 혼자 '나다움이란 뭘까' 생각에 잠겼다가]], [[本:아침엔 다시 친구 고민 들어 주는 쪽으로 돌아가 있음]]."]}, "ESFJ>ENFJ": {"karai": "상대를 위해서라면서, 내가 그린 이상대로 상대가 자라면 제일 기뻐함.", "name": "꿈까지 챙기는 총무", "atari": ["[[本:친구 하소연만 들어 줄 생각이었는데]], [[今:어느새 그 사람 인생 설계까지 같이 고민하고 있음]].", "[[本:눈앞의 사람이 웃고 있으면 만족했는데]], [[今:지금은 '이 사람의 가능성'까지 보여 버림]]."]}, "ESFJ>ENFP": {"karai": "자유롭게 사는 것 같아도, 좋아요 적은 게시물은 새벽에 몰래 지움.", "name": "계획을 깜빡한 분위기 메이커", "atari": ["[[今:즉흥으로 \"지금 모이자!\" 하고 부르면서]], [[本:속으로는 모두의 막차 시간을 확실히 찾아 둠]].", "[[今:새 가게를 발견할 때마다]], [[本:'다들 좋아할까'부터 생각하고 나서 사진을 찍고 있음]]."]}, "ESFJ>ISTJ": {"karai": "\"규칙이니까\"라고 딱 잘라 말하지만, 그 규칙의 절반은 '다들 곤란하지 않게'로 되어 있음.", "name": "티 안 나는 배려왕", "atari": ["[[今:담담하게 일만 하는 것처럼 보여도]], [[本:기운 없는 동료는 제일 먼저 알아챔]].", "[[今:회의에선 필요한 말만 하면서]], [[本:쉬는 시간 잡담이 되면 갑자기 목소리가 밝아짐]]."]}, "ESFJ>ISFJ": {"karai": "안 튀어도 된다면서, 내 배려를 아무도 몰라주면 살짝 삐짐.", "name": "무대 뒤로 간 총무", "atari": ["[[今:뒤풀이에선 구석 자리에 있으면서]], [[本:모두의 잔이 비지 않게 눈만은 계속 움직이고 있음]].", "[[本:여러 사람의 '고마워'를 좋아하던 사람이]], [[今:지금은 한 사람의 한마디로 일주일을 버팀]]."]}, "ESFJ>ESTJ": {"karai": "정론으로 밀어붙이지만, 상대가 울 것 같은 순간 전부 뒤집을 준비가 되어 있음.", "name": "비즈니스 모드의 총무", "atari": ["[[今:숫자로 몰아붙인 회의가 끝난 뒤]], [[本:화장실에서 '아까 너무 심했나' 하고 혼자 반성회 중]].", "[[今:효율 중시 캐릭터가 몸에 배어 가지만]], [[本:마감 어긴 사람에게도 그만 \"몸은 괜찮아?\"부터 물어봄]]."]}, "ESFJ>ESFJ": {"karai": "모두를 위해서라면서, 고맙단 말 못 들으면 은근히 상처받고 그걸 계속 기억함.", "name": "타고난 명총무", "atari": ["누가 \"어디 갈래?\"라고 말하는 순간 가게 후보 세 곳이랑 예약 가능 여부까지 뽑아 놓음.", "남의 생일이랑 좋아하는 음식 외우는 게 특기라, 본인보다 먼저 축하 준비를 시작함."]}, "ESFJ>ISTP": {"karai": "사람한테 관심 없는 척하지만, 직장 내 인간관계 상관도는 누구보다 정확히 파악 중.", "name": "싹싹함을 넣어 둔 장인", "atari": ["[[今:혼자 묵묵히 작업하는 게 편해졌는데]], [[本:누가 곤란해하면 손이 알아서 도와주러 감]].", "[[今:휴일엔 일부러 아무하고도 말 안 하는 날을 만들면서]], [[本:저녁이 되면 왠지 누군가에게 전화하고 싶어짐]]."]}, "ESFJ>ISFP": {"karai": "흐름에 맡긴다면서, 놀 날짜 후보만은 머릿속에 세 개 찜해 둠.", "name": "마이웨이 배려왕", "atari": ["[[今:좋아하는 것만 골라 살고 싶은데]], [[本:선물 고를 땐 상대 취향을 철저하게 리서치함]].", "[[今:\"기분 따라 정하자\"고 말할 수 있는 내가 좋아지기 시작했지만]], [[本:말하고 나서 살짝 불안해짐]]."]}, "ESFJ>ESTP": {"karai": "쿨한 척해도, 읽씹당하면 채팅방을 세 번쯤 들락날락함.", "name": "흥으로 움직이는 챙김이", "atari": ["[[今:그 자리 기세로 약속에 올라타면서]], [[本:뒤처질 것 같은 사람 없나 계속 곁눈질하고 있음]].", "[[今:\"일단 가자\"라고 말하는 게 묘하게 짜릿함]]. 그래도 [[本:도착한 가게에선 모두의 음료부터 주문해 둠]]."]}, "ESFJ>ESFP": {"karai": "흥으로 산다면서, 분위기 안 뜬 날엔 집 가는 길에 원인 분석해 버림.", "name": "계획을 내려놓은 회식 부장", "atari": ["[[今:그날 분위기로 모이는 게 좋아졌는데]], [[本:못 온 사람용 사진만큼은 꼭 찍어 둠]].", "[[今:예약 없이 빈 가게에 뛰어드는 날이 더 즐거움]]. 그래도 [[本:인원수만큼 자리가 있는지는 제일 먼저 확인함]]."]}, "ENFJ>INTJ": {"karai": "사람한테 기대 안 하기로 해놓고, 기대 너무 해서 혼자 실망하는 걸 못 끊음.", "name": "이상을 숨긴 참모", "atari": ["[[今:차갑게 바른 말을 한 뒤]], [[本:'상대를 위해서야' 하고 속으로 몇 번이나 변명하고 있음]].", "[[本:사람을 격려하며 이끌고 싶은 사람인데]], [[今:지금은 혼자 완벽한 계획을 짜는 쪽을 택하고 있음]]."]}, "ENFJ>INTP": {"karai": "인간관계 귀찮다지만, 사실 챙겨주고 싶은 상대가 없는 것뿐일 수 있음.", "name": "열정을 숨긴 연구자", "atari": ["[[今:혼자 논리를 굴리는 시간을 좋아하면서]], [[本:인생 상담을 받는 순간 뜨거운 명언이 멈추질 않음]].", "친구 꿈 이야기를 들으면 [[今:응원보다 \"그거 근거 있어?\"가 먼저 입에서 나와 버림]]."]}, "ENFJ>ENTJ": {"karai": "합리적인 리더를 연기하지만, 뒤에선 멤버들 반응 신경 쓰느라 꽤 지쳐 있음.", "name": "너무 열혈인 리더", "atari": ["[[今:숫자로 부하 직원을 몰아붙이면서]], [[本:면담에선 한 명 한 명의 꿈까지 물어보고 확실히 기억해 둠]].", "[[本:마음을 우선하고 싶은 사람인데]], [[今:지금은 상대 말이 끝나기도 전에 \"그래서 결론은?\"이라고 해 버림]]."]}, "ENFJ>ENTP": {"karai": "삐딱한 척하지만, \"고마워\" 한마디에 1초 만에 순한 얼굴로 돌아옴.", "name": "토론으로 사랑을 말하는 사람", "atari": ["[[今:일부러 반대 의견을 내서 토론을 달구면서]], [[本:마지막엔 반드시 모두가 납득하는 형태로 정리함]].", "[[今:후배 기획을 들으면 먼저 구멍부터 찾다가]], [[本:지적한 뒤 허둥지둥 좋은 점을 다섯 개 꼽음]]."]}, "ENFJ>INFJ": {"karai": "지켜보는 중이라더니, 상대가 내가 생각한 길을 고를 때까지 속으로 계속 조마조마함.", "name": "조용히 지켜보는 응원단장", "atari": ["[[本:많은 사람 앞에서 연설하는 것보다]] [[今:지금은 패밀리 레스토랑에서 한 사람 이야기를 세 시간 듣는 게 더 맞음]].", "[[今:고민 있는 사람을 알아채도 말은 안 걸고]], [[本:상대가 말하기 편한 분위기부터 먼저 만들어 둠]]."]}, "ENFJ>INFP": {"karai": "나답게 산다면서, '나다운지'를 주변 반응으로 확인하고 있음.", "name": "돌봄을 쉬는 몽상가", "atari": ["[[今:내 마음을 소중히 하기로 해 놓고]], [[本:정신 차려 보면 일기엔 남의 마음 얘기만 쓰고 있음]].", "[[今:약속 없는 휴일에 혼자 영화 보다 울고]], [[本:그대로 조연의 앞날까지 진심으로 걱정하고 있음]]."]}, "ENFJ>ENFJ": {"karai": "남을 위해 애쓰는 내가 너무 좋아서, 거절당하면 상대보다 내가 더 데미지 받음.", "name": "타고난 응원단장", "atari": ["친구의 작은 도전에도 진심으로 박수 치다가, 본인보다 먼저 울 것 같아짐.", "부탁받지도 않았는데 후배 진로를 같이 고민하다가, 어느새 면담 일정까지 잡아 둠."]}, "ENFJ>ENFP": {"karai": "자유인처럼 보여도, 다들 잘 따라오는지만큼은 몇 번이고 뒤돌아 확인함.", "name": "설렘 우선 오지랖", "atari": ["[[今:즉흥으로 새로운 걸 시작하면서]], [[本:어느새 같이 시작한 친구까지 챙기고 있음]].", "[[本:계획을 세워 모두를 이끌고 싶은 사람인데]], [[今:지금은 그때그때 번뜩임으로 방향을 휙휙 바꿈]]."]}, "ENFJ>ISTJ": {"karai": "일에 감정 안 끌어들인다면서, 송별회 스피치에선 대개 제일 먼저 울고 있음.", "name": "열정을 넣어 둔 꼼꼼이", "atari": ["[[今:담담하게 매뉴얼대로 일하면서]], [[本:신입의 성장만큼은 몰래 메모로 기록하고 있음]].", "[[本:큰 이상을 이야기하고 싶은 사람인데]], [[今:지금은 \"전례대로 하죠\"라고 말하는 게 더 안심이 돼 버림]]."]}, "ENFJ>ISFJ": {"karai": "조용히 서포트하는 줄 알아도, 상대 인생의 중요한 결정엔 확실히 훈수 둠.", "name": "앞에 나서지 않는 명매니저", "atari": ["[[今:모두 앞에서 격려하는 역할은 내려놨는데]], [[本:간식에는 한 명 한 명 다른 메모를 붙여 둠]].", "[[本:다 같이 큰 꿈을 좇는 것보다]] [[今:지금은 눈앞의 한 사람이 제대로 웃고 있는지가 더 신경 쓰임]]."]}, "ENFJ>ESTJ": {"karai": "규칙에 엄한 상사를 연기하지만, 누가 울며 매달리면 결국 규칙 굽혀줌.", "name": "이상을 일정표에 적는 사람", "atari": ["[[本:사람의 가능성을 믿고 싶은 사람인데]], [[今:지금은 \"그래서 언제까지 돼?\"라고 기한부터 물어 버림]].", "[[今:팀 목표를 숫자로 관리하면서]], [[本:달성한 날엔 모두에게 손편지를 건네고 있음]]."]}, "ENFJ>ESFJ": {"karai": "모두를 돌보는 줄 알았는데, 돌봄받는 쪽의 자유는 꽤 뺏고 있음.", "name": "눈앞 전문 오지랖", "atari": ["[[本:큰 꿈을 이야기하는 대신]] [[今:지금은 이번 주 회식 장소 고르기에 온 힘을 쏟고 있음]].", "[[本:남의 미래를 같이 그리는 것보다]] [[今:\"오늘 밥은 잘 챙겨 먹었어?\" 카톡 보내느라 바쁜 나날]]."]}, "ENFJ>ISTP": {"karai": "건조하게 사는 줄 알아도, 감동 영상 보면 누구보다 빨리 울고 있음.", "name": "사랑을 공구함에 넣은 사람", "atari": ["[[今:말로 격려하는 건 그만뒀는데]], [[本:친구 자전거가 고장 나면 말없이 고치러 가 버림]].", "[[本:사람 마음에 불을 지피고 싶은 사람인데]], [[今:지금은 \"딱히 아무거나 상관없어\"라고 말하는 일이 늘었음]]."]}, "ENFJ>ISFP": {"karai": "아무한테도 간섭 안 한다면서, 좋아하는 사람 고민엔 전력으로 오지랖 부림.", "name": "혼자 피어난 응원단장", "atari": ["[[本:사람을 이끄는 역할을 내려놓고 나서]] [[今:좋아하는 소품이나 음악을 고르는 시간이 이제야 즐거워짐]].", "[[今:많은 사람 앞엔 안 서게 됐지만]], [[本:마음에 드는 사람에게만은 손수 만든 걸 살짝 건네고 있음]]."]}, "ENFJ>ESTP": {"karai": "가벼운 척하지만, 진지한 상담 들어오면 아직도 아침까지 이야기함.", "name": "열정을 행동으로 바꾼 사람", "atari": ["[[今:격려의 말보다 몸이 먼저 움직이게 되면서]], [[本:어느새 곤란한 사람 짐을 전부 들고 있음]].", "[[本:이상을 말해서 사람을 움직이고 싶은 사람인데]], [[今:지금은 \"일단 해 보자\"로 밀어붙이고 있음]]."]}, "ENFJ>ESFP": {"karai": "재밌으면 그만이라고 웃지만, 사실 모두의 인생을 조금 더 낫게 만들고 싶은 야망이 있음.", "name": "그 자리를 밝히는 무드메이커", "atari": ["[[今:앞일은 생각 말고 오늘을 즐기기로 했는데]], [[本:귀갓길엔 모두의 내일 일정을 신경 쓰고 있음]].", "[[今:회식에서 모두를 웃기면서]], [[本:구석에서 겉도는 사람이 있으면 바로 옆자리에 가서 앉음]]."]}, "ENTJ>INTJ": {"karai": "앞에 안 나서는 건 겸손해서가 아니라, 설명하는 수고를 생략하는 것뿐일 수 있음.", "name": "앞에 나서지 않는 사령관", "atari": ["[[今:회의에선 한마디도 안 하면서]], [[本:끝날 무렵엔 내가 준비한 결론으로 이야기가 정리되어 있음]].", "[[今:누가 정하든 똑같다고 말하면서]], [[本:내 제안이 안 통한 날엔 귀갓길에 전략을 다시 짬]]."]}, "ENTJ>INTP": {"karai": "흐름에 맡긴다면서, 나 모르게 정해진 일엔 반드시 이유를 물음.", "name": "결단 보류 중인 사장님", "atari": ["[[本:빨리 결론을 내고 싶은 사람인데]], [[今:지금은 찾아볼수록 선택지가 늘어서 못 정함]].", "[[今:혼자 가설 세우며 놀고 있다가도]], [[本:누가 질질 끌며 말하면 갑자기 진행을 잡기 시작함]]."]}, "ENTJ>ENTJ": {"karai": "\"의견 있는 사람?\" 묻지만, 그건 내 의견에 찬성하는 사람 세는 것뿐.", "name": "타고난 결정권자", "atari": ["점심 메뉴로 다들 고민하고 있으면, 3초 만에 정해서 전원 몫 주문까지 끝내 둠.", "목표를 세우면 역산해서 움직이는 게 당연해서, 계획 없는 인생이 솔직히 잘 이해가 안 됨."]}, "ENTJ>ENTP": {"karai": "유연해졌다고 스스로 생각하지만, 남들 눈엔 결정 속도가 예전 그대로임.", "name": "진행하면서 탈선하는 사람", "atari": ["[[本:회의에서 결론 내는 역할일 텐데]], [[今:재밌는 안이 떠오를 때마다 본인이 안건을 늘리고 있음]].", "[[本:이기기 위한 계획을 세웠는데]], [[今:도중에 떠오른 다른 작전을 시험해 보고 싶어서 근질근질함]]."]}, "ENTJ>INFJ": {"karai": "온화한 사람인 줄 알지만, 앞뒤 안 맞는 사람과는 조용히 손절 중.", "name": "헤아리며 이끄는 사령관", "atari": ["[[今:상대 마음을 헤아리며 이야기를 들으면서]], [[本:머릿속에선 이미 착지점까지 정해 둠]].", "[[本:당당히 앞에 나서서 지휘하고 싶은 사람인데]], [[今:지금은 상대가 스스로 깨닫게 하는 방식으로 이끌려 함]]."]}, "ENTJ>INFP": {"karai": "싸움은 싫다면서, 진 경기만은 몇 년이 지나도 디테일하게 기억함.", "name": "꿈을 말하는 전직 사장님", "atari": ["[[今:'좋아하는 걸 하면 돼' 하고 스스로 타이르면서도]], [[本:좋아하는 일에서마저 1등이 하고 싶어짐]].", "[[今:혼자 망상에 빠져 있어도]], [[本:그 망상 속에선 내가 확실하게 조직을 이끌고 있음]]."]}, "ENTJ>ENFJ": {"karai": "사랑 넘치는 리더를 지향하지만, 칭찬 뒤엔 늘 다음 할당량이 있음.", "name": "뜨겁게 말하는 실력주의자", "atari": ["[[今:멤버들을 격려하는 연설을 하면서]], [[本:속으로는 다음 인사 배치도 확실히 생각해 둠]].", "[[本:바른 말로 밀어붙이고 싶은 사람인데]], [[今:지금은 상대 의욕이 꺾이지 않는 말투를 고르고 있음]]."]}, "ENTJ>ENFP": {"karai": "자유롭게 사는 것처럼 보여도, 남들보다 뒤처졌다는 걸 안 순간 진심 모드 돌입.", "name": "야망을 설렘으로 포장한 사람", "atari": ["[[今:\"재밌겠다, 해 보자!\"로 시작한 일이]] [[本:반년 뒤엔 왠지 사업 계획이 되어 있음]].", "[[今:'설레는지 아닌지'로 정했다고 말하면서]], [[本:뒤에선 이길 가능성도 확실히 계산해 둠]]."]}, "ENTJ>ISTJ": {"karai": "현실파를 자처하지만, 승진 기회 오는 순간 누구보다 빠르게 손 듦.", "name": "절차를 지키는 야심가", "atari": ["[[今:정해진 절차를 묵묵히 해내면서]], [[本:속으로는 '나라면 이 부서를 이렇게 바꾼다' 생각하고 있음]].", "[[本:큰 목표를 터뜨리고 싶은 사람인데]], [[今:지금은 확실히 할 수 있는 것만 입 밖에 내게 됨]]."]}, "ENTJ>ISFJ": {"karai": "서포트 역할이 체질이라면서, 서포트 방식엔 일절 참견 못 하게 함.", "name": "앞치마를 두른 사장님", "atari": ["[[今:부탁받은 잡무를 정성껏 해내면서]], [[本:어느새 그 잡무의 구조째로 다시 만들고 있음]].", "[[今:\"어떻게 하고 싶어?\" 하고 상대 바람을 먼저 묻게 됐지만]], [[本:선택지는 대부분 내가 준비해 둔 것임]]."]}, "ENTJ>ESTJ": {"karai": "현실적이 됐다지만, 속으론 아직 천하 제패 계획 포기 안 함.", "name": "현실파로 전향한 야심가", "atari": ["[[本:10년 뒤 꿈을 이야기하는 대신]] [[今:지금은 이번 달 숫자를 확실히 달성하는 데 불타고 있음]].", "새 아이디어를 들으면 [[今:일단 \"그거 누가 언제 해?\" 하며 담당표부터 만들기 시작함]]."]}, "ENTJ>ESFJ": {"karai": "분위기를 소중히 한다면서, 최종 결정권만은 절대 안 놓음.", "name": "모두에게 사랑받고 싶은 총사령관", "atari": ["[[今:회식 총무를 완벽하게 해내면서]], [[本:겸사겸사 참석자 인맥도까지 머리에 넣어 둠]].", "[[今:모두의 체면을 세워 줄 안을 찾느라 회의가 길어질 때마다]], [[本:'예전의 나라면 5분이면 정했을 텐데' 생각함]]."]}, "ENTJ>ISTP": {"karai": "독고다이인 척하지만, 무리 만들라 하면 하룻밤 만에 조직도 그릴 수 있음.", "name": "지휘를 그만둔 장인 기질", "atari": ["[[本:사람을 움직여 큰 성과를 내고 싶은 사람인데]], [[今:지금은 내 손으로 할 수 있는 범위에 만족하고 있음]].", "[[今:참견 안 하기로 정해 놓고]], [[本:비효율적으로 작업하는 사람을 보면 말없이 도구를 가져가 버림]]."]}, "ENTJ>ISFP": {"karai": "다툼엔 관심 없다지만, 승부욕은 1밀리도 안 고쳐졌음.", "name": "야망 휴업 중인 자유인", "atari": ["[[今:느긋하게 취미를 즐길 생각이었는데]], [[本:어느새 그 취미 모임에서 진행 역할을 맡고 있음]].", "[[今:남과 비교 안 하기로 하고 SNS 보는 시간을 줄였는데]], [[本:친구 승진 소식만큼은 묘하게 귀에 남음]]."]}, "ENTJ>ESTP": {"karai": "즉흥적으로 보여도, 본인 머릿속에선 전부 '예상 범위 내'로 처리됨.", "name": "계획보다 먼저 움직이는 장군", "atari": ["[[本:장기 전략을 세운 다음 공격하고 싶은 사람인데]], [[今:지금은 현장에서 정하는 게 이긴다는 걸 알아 버림]].", "[[今:그 자리 분위기로 시작한 놀이에서도]], [[本:정신 차려 보면 규칙을 만들어서 승패를 가리고 있음]]."]}, "ENTJ>ESFP": {"karai": "흥으로 사는 척하지만, 눈에 띄는 자리는 매번 확실히 챙기러 감.", "name": "분위기 잘 띄우는 야심가", "atari": ["[[今:파티에서 누구보다 즐거워하면서]], [[本:끝날 무렵엔 다음 기획의 주최자로 정해져 있음]].", "[[今:일 상대를 '같이 있으면 즐거운지'로 고르게 됐지만]], [[本:고른 사람은 대체로 일도 잘함]]."]}};
var PS={"INTJ": {"catch": "회의가 시작되기 전에, 이미 답이 나와 있는 사람.", "overview": "다들 의논을 시작할 즈음, 머릿속에는 벌써 답이 나와 있는 사람이에요. '앞으로 어떻게 될까'를 생각해서, 헛수고가 적은 방법을 골라요. 회의 내내 조용히 있다가 마지막 한마디로 이야기를 정리해요. 그런 일이 자주 있어요. 말수는 적지만, 상담하면 정말 도움이 되는 답을 돌려줘요.", "strengths": ["앞일을 생각해서 준비해요｜여행 가면 비 올 때 갈 곳까지 정해 두고 출발해요. 덕분에 나중에 곤란해지는 일이 별로 없어요.", "혼자서 차분히 생각해요｜남의 의견만으로 정하지 않아요. 직접 알아보고 납득한 뒤에 정해요.", "쓸데없는 수고를 알아채요｜'이 작업, 없어도 되지 않아?' 하고 빨리 알아채요. 다들 일이 줄어요."], "pitfalls": ["결론만 말해 버려요｜내 머릿속에서는 다 이어져 있어도, 상대에게는 갑작스럽게 들려요. 결론 뒤에 '왜냐하면'을 한마디 붙여 보세요.", "남이 돌아가는 게 답답해요｜더 빠른 방법이 보여서 애가 타요. 끼어들기 전에, 상대가 하는 방식을 끝까지 지켜봐 주세요.", "남에게 부탁을 안 해요｜'내가 하는 게 빠르지' 하며 결국 직접 해 버려요. 이번 주에는 작은 일 하나를 남에게 부탁해 보세요."], "relationships": "친구는 적어도 괜찮다고 생각해요. 단톡방에서는 조용해도, 따로 상담을 받으면 긴 답장을 보내요. 친해진 사람과는 오래 가요. 혼자만의 시간을 가만히 내버려 두는 사람이 가장 편해요.", "love": "좋아하게 되기까지 시간이 걸려요. 하지만 사귀기로 정하면 아주 진지해요. 마음은 '좋아해'보다 미래 이야기로 전하는 편이에요. 데이트 뒤에 '또 가자' 하고 한마디 보내 보세요. 상대가 기뻐해요.", "work": "목표가 뚜렷하고, 방법은 맡겨 주는 곳이 잘 맞아요. '저 사람한테 물어보면 어떻게 할지 알 수 있어' 하며 다들 의지해요. 이유를 알 수 없는 규칙이나 아무것도 안 정해지는 회의가 이어지면 지쳐요. 집중할 시간을 먼저 일정에 넣어 두면 일이 잘 풀려요.", "jobs": ["경영기획·사업전략", "시스템 설계", "연구직", "데이터 분석가"], "growth": "당신의 결론은 대체로 맞아요. 오늘 무언가를 전할 때, '왜 그렇게 생각했는지'를 한마디 붙여 보세요.", "A": "한번 정하면 망설이지 않고 나아가요. 주변이 웅성거려도 별로 신경 쓰지 않아요.", "T": "계획에 이상한 데가 없는지 몇 번이고 다시 봐요. 불안할 때는 믿을 만한 사람에게 한번 이야기를 들어 달라고 하면 마음이 가라앉아요."}, "INTP": {"catch": "'왜 그럴까' 하고 찾아보다가, 어느새 한밤중인 사람.", "overview": "궁금한 게 생기면 몇 시간이고 찾아보는 사람이에요. 답을 외우기보다 '왜 그렇게 되지?' 하고 생각하는 걸 좋아해요. 자기 전에 잠깐만 찾아보려다가, 정신 차려 보면 새벽 2시. 그런 밤이 자주 있어요. 마이페이스처럼 보이지만, 이야기해 보면 생각지도 못한 답이 돌아와요.", "strengths": ["구조를 잘 알아요｜복잡한 이야기를 들어도 '그러니까 이런 거지?' 하고 짧게 정리할 수 있어요.", "소문을 그대로 믿지 않아요｜'다들 그러던데' 하는 말을 들어도, 직접 찾아본 뒤에 믿어요.", "좋아하는 것에 푹 빠져요｜빠진 게임이나 분야는 어느새 꽤 잘 알게 돼 있어요."], "pitfalls": ["생각이 많아서 못 정해요｜'더 좋은 방법이 있을지도' 하다가 좀처럼 시작을 못 해요. '금요일까지 정하기'처럼 날짜를 스스로 정해 보세요.", "감정 이야기가 어려워요｜친구가 하소연하는데 해결 방법을 말해 버려요. 먼저 '그거 진짜 힘들었겠다'라고 말해 보세요.", "하다 만 일이 쌓여요｜새로 궁금한 게 생기면 하던 일이 중간에 멈춰요. 새로 시작하기 전에 하나만 끝내 보세요."], "relationships": "여럿보다 적은 사람과 좋아하는 이야기를 하는 게 더 즐거운 타입이에요. 곤란할 때 '찾아봤어' 하고 알려 주니까 다들 의지해요. 갑자기 말없이 생각에 잠겨도 신경 안 쓰고, '그거 재밌다' 하고 이야기에 끼어 주는 사람과는 이야기가 끝이 없어요.", "love": "'이 사람을 더 알고 싶다'에서 좋아하는 마음이 시작돼요. 이야기를 많이 하다 보면 가까워지는 타입이에요. 좋아하는 사람에게 보낼 답장을 너무 고민하다가 3일이 지나 있기도 해요. 짧아도 '오늘 이런 일 있었어' 하고 보내기만 하면 상대는 안심해요.", "work": "자기 속도로 생각할 수 있고, 새로운 걸 시도할 수 있는 일이 잘 맞아요. 원인을 찾거나 구조를 만드는 일로 칭찬받기 쉬워요. 같은 작업의 반복이나 의미를 모르겠는 보고가 이어지면 지쳐요. '무엇을 위해 하는지' 알면 집중할 수 있어요.", "jobs": ["프로그래머", "연구원", "데이터 사이언티스트", "게임 기획자"], "growth": "생각은 다 정리된 뒤에 말하지 않아도 괜찮아요. 오늘, 아직 반쯤인 아이디어를 누군가 한 명에게 말해 보세요.", "A": "떠오른 생각을 편하게 남에게 말해요. 생각이 아직 정리되지 않아도 괜찮아해요.", "T": "틀린 데가 없는지 꼼꼼히 확인하고 나서 내놓아요. 망설여질 때는 지금 아는 데까지만이라도 내놓아 보세요."}, "ENTJ": {"catch": "'그럼, 이렇게 하자' 하고 정해 주는 사람.", "overview": "다들 망설여서 이야기가 멈추면, '그럼 이렇게 하자' 하고 정해 주는 사람이에요. 목표가 정해지면 할 일의 순서를 바로 생각하고, 사람들에게 말을 걸어 진행해요. '어디 갈래?'에서 멈춰 있던 단톡방도 당신이 후보 3개를 내면 금방 정해져요. 엄격해 보일 때도, 좋은 결과를 내고 싶을 뿐이에요.", "strengths": ["망설이는 이야기를 정해요｜'아무거나 괜찮아'가 이어질 때 '오늘은 이걸로 하자' 하고 정할 수 있어요.", "할 일을 잘 나눠요｜큰 목표를 '오늘 할 일', '다음 주 할 일'로 나눌 수 있어요. 누가 뭘 할지도 금방 정해져요.", "어려울수록 의욕이 나요｜'그거 무리 아니야?'라는 말을 들으면 오히려 해 보고 싶어져요."], "pitfalls": ["남에게도 내 속도를 바라요｜다들 같은 속도로 움직일 수 있다고 생각해 버려요. 부탁하기 전에 '지금 바빠?' 하고 물어보세요.", "쉬면 마음이 불편해요｜쉬는 날에도 자꾸 뭔가를 하고 싶어져요. 주말에 반나절만, 아무 일정도 없는 시간을 만들어 보세요.", "지적이 먼저 나와요｜신경 쓰이는 점을 바로 말해서 상대가 풀이 죽을 때가 있어요. 지적하기 전에 잘한 점을 하나 말해 보세요."], "relationships": "친구들과 놀러 갈 때, 어느새 갈 곳과 시간을 정하고 있는 사람이에요. 의지받는 건 괜찮지만, 가끔 상대 이야기를 천천히 들어 주는 시간을 만들면 더 친해질 수 있어요. 의견을 분명하게 말해 주는 사람과는 좋은 관계가 돼요.", "love": "좋아하는 사람에게는 '좋아해'라고 솔직하게 말할 수 있어요. 데이트 계획도 꼼꼼히 세우고, 행동으로 아껴 줘요. 상대의 고민을 듣다가 어느새 개선안을 내고 있기도 해요. 그럴 때는 답을 내지 말고 '그랬구나' 하고 들어 주기만 하면 상대가 말하기 편해져요.", "work": "목표가 정해져 있고 크게 맡겨 주는 회사라면 힘을 낼 수 있어요. 프로젝트를 정리하거나 팀을 이끄는 역할로 의지받아요. 좀처럼 결정이 안 나는 회사나 성과가 잘 안 보이는 일이 이어지면 지쳐요. 결과를 낼수록 맡는 일이 늘어나요.", "jobs": ["회사 대표·창업가", "프로젝트 매니저", "컨설턴트", "영업 매니저"], "growth": "당신이 잠깐 조용해지면, 얌전한 사람이 말을 꺼내요. 오늘 회의 마지막에 '다른 의견 있어?' 하고 한 번만 물어보세요.", "A": "결정이 빠르고, 압박이 있는 자리에서도 당당하게 사람들을 이끌어요.", "T": "자잘한 걱정거리를 잘 알아채요. 완벽하게 하려고 너무 애쓸 때는 오늘 해낸 일을 세어 보세요."}, "ENTP": {"catch": "'반대로 말이야' 하고 다른 안을 내는 사람.", "overview": "다들 '보통 이렇게 하잖아' 하고 생각하는 것에 '반대로 이렇게 하면?' 하고 말할 수 있는 사람이에요. 이야기하다 보면 안이 계속 늘어나요. 그냥 수다였는데, 정신 차려 보면 새 기획 이야기가 돼 있기도 해요. 말다툼을 좋아하는 것처럼 보이지만, 이기고 싶은 게 아니라 더 좋은 답을 찾고 싶을 뿐이에요.", "strengths": ["다른 방법을 금방 떠올려요｜의논이 막혀도 '그럼 이건?' 하고 계속 안을 낼 수 있어요.", "이야기하면서 아이디어가 커져요｜친구랑 수다 떨다 보면 작은 생각이 큰 이야기가 돼요.", "누구에게나 말을 걸어요｜윗사람에게도 처음 보는 사람에게도 편하게 말을 걸어요. 사람과 사람을 소개하는 것도 잘해요."], "pitfalls": ["끝까지 하는 게 어려워요｜처음엔 재밌는데, 마무리 단계가 되면 질려요. 마무리를 좋아하는 사람에게 마지막 부분을 도와 달라고 해 보세요.", "이야기에 너무 열을 올려요｜신나서 상대가 지친 걸 못 알아챌 때가 있어요. 가끔 '넌 어떻게 생각해?' 하고 상대에게 넘겨 보세요.", "재밌어 보이는 이야기에 바로 응해요｜제안받을 때마다 OK 하다가 감당이 안 돼요. 답하기 전에 이번 주 일정을 한번 보세요."], "relationships": "어떤 모임에도 금방 섞여서, 화제를 던지고 분위기를 띄워요. 떠오른 생각을 메신저로 보내서 이야기를 넓히는 것도 잘해요. 가끔은 반대 의견도 말해 주는 사람이 좋아요. 말다툼을 즐길 수 있는 친구와는 몇 년이 지나도 사이가 좋아요.", "love": "이야기하면 즐거운 사람이나, 모르는 걸 알려 주는 사람을 좋아하게 돼요. 새로운 곳에 데려가서 데이트를 즐겁게 만들려고 해요. 농담으로 한 말에 상대가 진짜로 상처받기도 해요. 진지한 이야기를 할 때는 먼저 '그랬구나' 하고 들어 주세요.", "work": "새로운 것에 도전하고 아이디어를 자유롭게 낼 수 있는 곳을 좋아해요. 기획을 시작하거나, 문제를 새로운 방법으로 푸는 역할로 활약해요. 매일 같은 작업만 하면 지쳐요. 변화가 많은 곳일수록 즐겁게 일할 수 있어요.", "jobs": ["신규 사업·기획직", "창업가", "마케터", "광고 기획자"], "growth": "아이디어는 이미 많이 나와 있어요. 그중 하나를 골라서, 맨 처음 할 일을 하나 정해 보세요.", "A": "떠오르면 그날 바로 움직이기 시작해요. 잘 안 돼도 크게 풀이 죽지 않아요.", "T": "떠오른 생각을 '정말 될까?' 하고 한 번 확인해요. 사람들 반응을 잘 보니까 말하는 방식이 좋아요."}, "INFJ": {"catch": "'괜찮아' 한마디로, 기운이 없다는 걸 아는 사람.", "overview": "상대의 표정이나 목소리, 답장 속도가 조금만 달라져도 알아채는 사람이에요. 친구의 '괜찮아'를 듣고, 안 괜찮다는 걸 알아 버려요. '어떻게 알았어?' 하고 놀라는 사람도 있어요. 마음속에 '이렇게 되면 좋겠다'는 생각이 있어서, 거기에 가까워지면 기뻐요. 차분하고 잘 들어 주지만, 양보 못 하는 건 분명해요.", "strengths": ["기운 없는 사람을 알아채요｜다 같이 이야기하고 있어도, 혼자만 웃지 않는 사람을 알아채요. 나중에 '무슨 일 있어?' 하고 말을 걸 수 있어요.", "이야기를 끝까지 들어요｜상대가 다 말할 때까지 잘 기다려요. '이 사람한테는 말할 수 있어' 하며 중요한 상담을 받아요.", "자기 생각이 있어요｜주변이 다 찬성해도, 아니라고 생각하면 휩쓸리지 않아요."], "pitfalls": ["남의 고민을 내 일처럼 떠안아요｜친구 상담을 듣고 나면 나까지 우울해져요. 다 듣고 나면 좋아하는 음악을 들으면서 기분을 바꿔 보세요.", "너무 참아요｜다투기 싫어서 작은 불만을 쌓아 둬요. 쌓이기 전에 '좀 신경 쓰이는 게 있어서' 하고 가볍게 말해 보세요.", "스스로에게 엄격해요｜생각대로 안 되면 많이 우울해져요. '오늘은 반만 해도 OK'라고 정해 보세요."], "relationships": "친구가 많지 않아도 오래 지낼 수 있는 사람을 아껴요. 모임에서는 듣는 쪽이 되기 쉽고, '이야기하면 마음이 편해져'라는 말을 들어요. 만나는 횟수보다, 만났을 때 제대로 이야기할 수 있는지가 중요한 타입이에요. 말없이 있는 시간도 어색하지 않은 사람과 잘 맞아요.", "love": "이야기하다 보면 '이 사람 생각하는 방식, 좋다' 하고 조금씩 좋아하게 돼요. 상대가 평소와 다르면 바로 알아채고, 말보다 행동으로 다정하게 대해요. 상대에게 너무 맞추다가 내가 가고 싶은 가게를 말 못 할 때도 많아요. '여기 가고 싶어' 하나만 말해도 두 사람 거리가 가까워져요.", "work": "의미가 있다고 느끼는 일이라면 힘을 낼 수 있어요. 남에게 도움이 되고 있다는 걸 알면 더 그래요. 상담을 해 주거나, 사람들 마음을 생각해서 기획하는 일에서 환영받아요. 숫자만 쫓는 곳이나 회의만 많은 곳에서는 피로가 쌓여요. 일주일에 한 번, 혼자 조용히 지내는 시간을 만들면 컨디션이 유지돼요.", "jobs": ["상담사·카운슬러", "편집자·작가", "인사·채용 담당", "보육교사·교사"], "growth": "남의 마음을 잘 알아채는 사람일수록, 내 마음은 뒤로 미루기 쉬워요. 오늘 밤 자기 전에, 오늘 기뻤던 일을 하나 떠올려 보세요.", "A": "자기 생각을 믿고 차분하게 움직여요. 필요할 때는 '나는 이렇게 생각해' 하고 분명하게 말할 수 있어요.", "T": "남이 기분 나빠하지 않을까 많이 신경 써요. 그만큼 말을 다정하게 골라요. 너무 신경 쓴 날은 '오늘 충분히 배려했어' 하고 생각하고 쉬세요."}, "INFP": {"catch": "머릿속에서 자꾸 '만약에' 이야기를 떠올리는 사람.", "overview": "지하철을 타고 있을 때나 쉬는 날 오후, 머릿속에서 '만약 이랬다면' 하는 상상이 시작되는 사람이에요. 좋아하는 음악이나 책, 풍경에 마음이 잘 움직이고, 느낀 걸 천천히 음미해요. 역에서 집까지 걷는 10분 동안, 머릿속에서는 이야기 하나가 완성돼 있기도 해요. '이것만은 소중히 하고 싶다'가 분명해서, 거기에 안 맞는 일에는 의욕이 안 나요. 얌전해 보여도 이야기해 보면 독특하고 재밌는 사람이에요.", "strengths": ["작은 일에도 마음이 움직여요｜길가의 꽃이나 친구의 별생각 없는 한마디를 알아채고, 뭉클해할 수 있어요.", "힘든 사람 마음을 알아요｜우울한 친구의 이야기를 부정하지 않고 들어 줘요. 곁에 있기만 해도 안심이 돼요.", "마음을 표현할 수 있어요｜그림이나 노래, 사진 같은 걸로 느낀 걸 표현하는 걸 잘해요. 말하기 어려운 것도 부드럽게 말할 수 있어요."], "pitfalls": ["생각이 많아서 시작을 못 해요｜상상이 커져서 첫걸음이 무거워져요. '준비만 하자' 하고 도구를 꺼내는 데까지 해 보세요.", "하고 싶은 말을 삼켜요｜상대에게 상처 주기 싫어서, 의견을 말 안 하고 끝나요. '나는 이게 좋은 것 같아' 하고 가볍게 말해 보세요.", "자기를 탓해요｜잘 안 되면 '내 탓이야' 하고 생각해 버려요. 친구에게 해 줄 말을 나 자신에게도 해 주세요."], "relationships": "마음 맞는 사람과 적은 인원으로 천천히 이야기하는 걸 좋아해요. 친해지면 좋아하는 것 이야기가 멈추지 않아요. 싸움을 싫어해서, 어색한 분위기를 풀어 주는 역할이 되기 쉬워요. 재촉하지 않고, 당신이 좋아하는 걸 재밌어해 주는 사람과 있으면 마음이 놓여요.", "love": "서로 진심으로 통하는 사람을 동경해요. 좋아하게 되면 상대가 좋아하는 노래를 몇 번이고 듣거나, 별생각 없이 한 말을 계속 기억하기도 해요. 아직 사귀지도 않았는데, 머릿속에서는 두 사람의 미래까지 상상하고 있기도 해요. 작은 마음부터 말로 꺼내 가면 사이가 깊어져요.", "work": "내 생각과 맞는 일이나, 누군가에게 도움이 되고 있다는 걸 아는 곳에서 의욕이 나요. 디자인이나 기획처럼 느끼는 힘을 쓰는 일을 잘해요. 실적 압박만 있는 곳에서는 의욕이 떨어져요. 일 속에서 '좋아하는 것'을 하나 찾으면 계속하기 쉬워요.", "jobs": ["작가·소설가", "일러스트레이터·디자이너", "심리·복지 직군", "영상 크리에이터"], "growth": "당신이 상상한 건, 형태로 만들면 사람들에게 전해져요. 오늘 좋다고 느낀 걸 하나 사진으로 찍어 보세요.", "A": "좋아하는 것에 자신이 있어요. 우울해져도 비교적 빨리 기운을 되찾아요. '나는 이게 좋아' 하고 당당하게 말해요.", "T": "기분의 작은 변화를 크게 느껴요. 그만큼 그림이나 음악에 마음이 담겨요. 불안한 날은 잠깐 산책을 나가 보세요."}, "ENFJ": {"catch": "부탁받기 전에, '도와줄까?' 하고 말하는 사람.", "overview": "곤란해하는 사람이 있으면, 부탁받기 전에 '도와줄까?' 하고 말을 거는 사람이에요. 후배가 고민하고 있으면 퇴근길에 밥을 먹자고 해서 이야기를 들어 줘요. 사람이 노력해서 달라지는 걸 보는 게 기뻐서, 어느새 모임을 이끄는 역할을 하고 있어요. 그만큼 내가 지쳤다는 건 잘 못 알아채요.", "strengths": ["남의 좋은 점을 말로 해 줘요｜'설명 알아듣기 쉬웠어', '그 머리 잘 어울려' 하고 알아채면 바로 전해요. 들은 사람은 자신감이 생겨요.", "의견을 모아요｜모두의 이야기를 듣고, 다들 납득하기 쉬운 안을 낼 수 있어요.", "말에 마음이 담겨 있어요｜당신이 '해 보자' 하고 말하면 다들 의욕이 생겨요."], "pitfalls": ["부탁받은 일을 쌓아 둬요｜'좋아'를 거듭하다가 어느새 손이 모자라요. 새로 맡는 건 하나를 끝낸 다음으로 해 보세요.", "기대에 너무 맞추려 해요｜실망시키기 싫어서 너무 애써요. 한 번만 '이번엔 못 해' 하고 말해 보세요.", "'너를 위해서'가 무거워져요｜좋은 뜻으로 한 조언이 상대에게는 부담일 때가 있어요. 조언하기 전에 '어떻게 해 주면 좋겠어?' 하고 물어보세요."], "relationships": "여러 모임에 아는 사람이 있어서, 이어 주는 역할이 되기 쉬워요. 친구의 좋은 점을 다른 친구에게 이야기하며 소개하는 것도 좋아해요. 당신의 약한 소리도 들어 주는 사람이 있으면 안심이 돼요. 받쳐 주기만 하는 게 아니라 받쳐 주는 상대와도 오래가요.", "love": "좋아하는 사람이 생기면, 기뻐하는 얼굴이 보고 싶어서 이것저것 해 줘요. 상대의 꿈이나 고민도 진지하게 들어요. 읽음 표시가 안 뜨기만 해도 '내가 뭐 잘못 말했나' 하고 보낸 메시지를 다시 읽기도 해요. 가끔은 기대는 쪽이 돼서, 해 줬으면 하는 걸 말해 보세요.", "work": "사람과 함께하는 일에서 누군가에게 도움이 되면 기뻐요. 리더나 가르치는 역할, 사이에서 조율하는 역할로 의지받아요. 혼자 하는 작업이 이어지는 곳이나 분위기가 험한 곳에서는 지쳐요. 사람이 성장하는 걸 가까이서 볼 수 있는 일이면 힘이 나요.", "jobs": ["교사·강사", "인사·교육 담당", "커리어 컨설턴트", "홍보·PR"], "growth": "남을 받쳐 주는 걸 잘하는 만큼, 내가 얼마나 지쳤는지도 봐 주세요. 오늘 부탁받은 일 하나는 '나중에 답할게' 하고 말한 뒤에 생각해 보세요.", "A": "자기 생각에 자신을 갖고, 모두에게 말을 걸 수 있어요. 많은 사람 앞에서도 긴장하지 않고 말해요.", "T": "한 사람 한 사람의 반응을 잘 보고 챙겨요. 남들이 나를 어떻게 생각할지 신경 쓰일 때는, 지금까지 남에게 해 준 일을 떠올려 보세요."}, "ENFP": {"catch": "'재밌겠다!' 하는 순간, 벌써 움직이고 있는 사람.", "overview": "새로운 가게, 처음 가는 곳, 아직 아무도 안 해 본 것. '재밌겠다!' 싶으면 바로 신이 나는 사람이에요. 떠오른 걸 바로 말하고 싶어서, 수다에서 아이디어가 계속 나와요. 처음 보는 사람과도 금방 친해져서, 어느새 상대가 좋아하는 걸 잔뜩 듣고 있어요. 활발해 보여도 사람 마음에 민감하고, 상처도 잘 받아요.", "strengths": ["아이디어가 계속 나와요｜이야기 하나에서 '그럼 이것도' 하고 계속 떠올려요.", "금방 친해져요｜처음 보는 사람과도 조금만 이야기하면 벌써 같이 웃고 있어요.", "주변을 하고 싶게 만들어요｜당신이 즐겁게 이야기하면 '나도 해 볼까' 하는 사람이 나와요."], "pitfalls": ["중간에 다른 데 눈이 가요｜시작한 일이 어느새 멈춰 있어요. 끝내고 싶은 걸 하나 골라서 '오늘은 여기까지' 하고 작게 정해 보세요.", "일정을 너무 많이 넣어요｜약속도 하고 싶은 것도 거절을 못 해서 일정이 꽉 차요. 일주일에 하루, 아무것도 안 넣는 날을 먼저 정해 보세요.", "자잘한 작업에 지쳐요｜반복 작업이나 서류 일은 자꾸 미뤄요. 좋아하는 음악을 틀어 놓고 15분만 해 보세요."], "relationships": "친구가 많고, 여러 타입의 사람과 친해질 수 있어요. 떠오르면 '지금 만날 수 있어?' 하고 보내서, 놀자고 먼저 말하는 쪽이 되기 쉬워요. 아이디어를 재밌게 들어 주는 사람이나, 적당할 때 '그거 돈 들어' 하고 말해 주는 사람과 잘 맞아요.", "love": "'이 사람이랑 있으면 즐거워'에서 좋아하는 마음이 시작될 때가 많아요. 좋아하게 되면 같이 가고 싶은 곳이 계속 떠올라요. 신난 밤에 보낸 긴 메시지를 다음 날 아침에 다시 읽고 부끄러워하기도 해요. 일상 속에서 작은 즐거움을 같이 만들면 오래가요.", "work": "새로운 걸 할 수 있고 사람 관계를 살릴 수 있는 일이라면, 매일이 즐거워져요. 기획이나 새 일 시작, SNS 홍보 같은 일을 잘해요. 같은 절차의 반복이나 꼼꼼하게 관리받는 곳에서는 의욕이 사라져요. 못하는 작업은 잘하는 사람과 나누면 좋아하는 일에 시간을 쓸 수 있어요.", "jobs": ["기획·마케팅", "카피라이터", "이벤트·여행 플래너", "스트리머·크리에이터"], "growth": "시작하는 힘은 이미 충분해요. 오늘, 하다 만 일 하나를 골라서 5분만 해 보세요.", "A": "떠오르면 망설이지 않고 해 봐요. 실패해도 '다음 거!' 하고 금방 털어요.", "T": "밝아 보여도 사실은 주변을 꽤 신경 쓰고 있어요. 지치면 혼자 좋아하는 걸 하는 시간을 가지세요."}, "ISTJ": {"catch": "정한 일을, 정한 대로 하는 사람.", "overview": "정한 일을 정한 대로 제대로 해내는 사람이에요. 제출물은 전날까지 끝나 있고, 약속 장소에는 10분 전에 도착해 있어요. 눈에 띄는 일은 안 하지만, 맡은 일은 끝까지 대충 하지 않아요. 처음엔 조금 말 걸기 어려워 보여도, 알고 지낼수록 '저 사람한테 맡기면 괜찮아'라는 말을 들어요. 혼자 집중할 수 있는 시간이 있으면 가장 힘이 나요.", "strengths": ["약속을 지켜요｜'해 둘게'라고 한 일은 꼭 해요. 마감도 안 늦어요.", "실수를 알아채요｜표의 숫자가 어긋나 있거나 순서가 빠져 있으면 바로 알아채요.", "티 안 나는 일을 꾸준히 해요｜아침 운동이나 공부를 몇 년이고 묵묵히 계속할 수 있어요."], "pitfalls": ["갑작스러운 일정 변경에 지쳐요｜당일에 '역시 장소 바꾸자'라는 말을 들으면 확 지쳐요. 나가기 전에 갈 곳 후보를 하나 더 정해 두세요.", "마음을 입 밖에 안 내요｜고맙다는 말도 불만도 안 해서 오해받을 때가 있어요. 도움을 받으면 '덕분에 살았어' 하고 말해 보세요.", "혼자 다 하려고 해요｜내가 하는 게 확실하다고 생각해 버려요. 일의 일부만 남에게 맡겨 보세요."], "relationships": "친구 수보다 오래가는 관계를 소중히 해요. 몇 년 만에 만나도 태도가 안 바뀌는 사람이에요. 시끌벅적한 자리가 이어지면 지치니까, 몇 명이서 차분하게 이야기할 수 있는 상대나 내 속도를 재촉하지 않는 사람과 있으면 편해요.", "love": "금방 좋아하게 되진 않지만, 정하면 한결같아요. 마음은 말보다 기념일을 기억하거나 역까지 바래다주는 걸로 전해요. 답장이 '알겠어'뿐이라서 '화났어?'라는 말을 듣곤 해요. 마지막에 '즐거웠어' 한마디만 붙여도 마음은 전해져요.", "work": "규칙과 담당이 분명한 곳에서 가장 힘이 나요. 정확함이 중요한 일이나, 마감까지 확실히 끝내는 역할로 의지받아요. 방침이 자꾸 바뀌는 곳이나, 준비 없이 갑자기 뭔가를 시키는 자리는 어려워요. 미리 정보를 모을 시간을 받으면 안심이 돼요.", "jobs": ["경리·회계", "공무원(행정직)", "품질관리", "시스템 유지보수·운영"], "growth": "늘 하던 방식에 조금만 다른 걸 더해 보세요. 오늘 집에 가는 길을 한 골목만 바꿔 보는 정도면 충분해요.", "A": "내 방식에 자신을 갖고 나아가요. 실수해도 오래 끌지 않고, 다음에 뭘 할지 바로 생각해요.", "T": "꼼꼼하게 확인해서 실수가 거의 없어요. 가끔은 '이 정도면 충분해' 하고 손을 멈춰 보세요."}, "ISFJ": {"catch": "말하기 전에, 살며시 도와주고 있는 사람.", "overview": "사람의 작은 변화를 알아채고, 말하기 전에 도와주는 사람이에요. 동료 안색이 안 좋으면 아무 말 없이 따뜻한 차를 놓아 둬요. 그런 일을 눈에 안 띄는 곳에서 계속하고 있어요. 사람들 취향이나 전에 들은 이야기를 잘 기억하고, 맡은 역할은 끝까지 제대로 해요. 어느새 '없으면 곤란한 사람'이 돼 있어요.", "strengths": ["사람의 변화를 알아채요｜머리를 자른 것이나 목소리가 평소보다 낮은 걸 바로 알아채요.", "잘 기억해요｜친구가 좋아하는 과자나 전에 말한 고민을 기억하고 있어요. '그걸 기억해 줬어?' 하고 다들 좋아해요.", "성실하게 계속해요｜눈에 안 띄는 정리나 준비도 대충 하지 않아요. 당신이 있으면 팀이 제대로 돌아가요."], "pitfalls": ["부탁받으면 거절을 못 해요｜거절하면 미안해서 자꾸 '좋아' 하고 말해 버려요. 바로 답하지 말고 '좀 생각해 볼게' 하고 말해 보세요.", "지쳐도 티를 안 내요｜걱정 끼치기 싫어서 한계까지 참아요. 가족이나 친구에게 '오늘 좀 피곤해' 하고 말해 보세요.", "새로운 게 불안해요｜익숙한 방식이 더 안심돼요. 새로운 건 하나만 작게 시도해 보세요."], "relationships": "시끌벅적한 모임의 한가운데보다, 가까운 사람을 아끼는 타입이에요. 감기 걸린 친구에게는 살며시 먹을 걸 챙겨 가요. 당신의 배려를 알아봐 주는 사람과는 오래 지내요.", "love": "좋아하는 사람에게는 뭔가를 해 주는 걸로 마음을 전해요. 상대가 좋아하는 요리를 만들어 주거나, 컨디션을 묻는 메시지를 자주 보내요. 선물을 받으면 기쁘기보다 먼저 '답례는 뭘로 하지' 하고 생각하기 쉬워요. 가끔은 '고마워'만 하고 받아 보세요.", "work": "사람을 받쳐 주는 역할이나 절차를 꼼꼼히 지키는 일에서 힘이 나요. 세심한 배려와 정확함으로 팀을 받쳐요. 눈에 안 띄는 일도 대충 하지 않지만, 칭찬을 못 받으면 조용히 지쳐요. '고마워'를 서로 말하는 곳을 고르면 오래 다닐 수 있어요.", "jobs": ["간호사", "보육교사", "의료사무", "총무·인사"], "growth": "남에게 주는 다정함을 조금은 나에게도 돌려 보세요. 오늘은 하나만, 내가 하고 싶은 일을 먼저 해 보세요.", "A": "할 수 있는 만큼만 맡을 수 있어서 너무 무리하지 않아요. 거절할 때도 크게 고민하지 않아요.", "T": "상대가 어떻게 생각할지 잘 생각해서 배려가 세심해요. 지친 날은 나에게도 다정하게 대해 주세요."}, "ESTJ": {"catch": "누가 뭘 할지, 바로 정해 주는 사람.", "overview": "일을 정리해서 모두를 앞으로 나아가게 하는 걸 잘하는 사람이에요. 의논이 안 모이면 '마감이랑 담당을 정하자' 하고 자연스럽게 진행을 맡아요. 정한 건 제대로 지키고, 주변도 지켜 줬으면 해요. 분명하게 말하니까 조금 무섭게 보일 때도 있지만, 곤란할 때 가장 든든해요. '말했으면 한다'가 입버릇이에요.", "strengths": ["준비가 빨라요｜축제나 회식 준비 때, 할 일을 순서대로 늘어놓고 바로 담당을 정할 수 있어요.", "책임감이 강해요｜맡은 일은 끝까지 내던지지 않아요. '맡기면 안심'이라고들 생각해요.", "규칙을 잘 지켜요｜분리수거도 시간도 꼬박꼬박 지켜요. 늘어지기 쉬운 분위기가 정신이 번쩍 들어요."], "pitfalls": ["말투가 세져요｜급할 때일수록 명령하는 것 같은 말투가 돼요. 부탁할 때는 먼저 '미안, 잠깐 괜찮아?'를 붙여 보세요.", "내 방식을 고집해요｜잘됐던 방법을 믿고 있어요. 이번 한 번만 다른 사람 방식으로 해 보세요.", "맡기고 나서 참견해요｜맡겨 놓고도 '이렇게 하는 게 좋아' 하고 말해 버려요. 맡겼으면 끝날 때까지 기다려 보세요."], "relationships": "잘 챙겨 주고, 친구들 사이에서 자연스럽게 리더 역할을 해요. 동창회나 회식 총무도 자주 맡아요. 약속을 지키는 사람이나 의견을 분명하게 말해 주는 사람을 믿어요. 돌려 말하면 조금 곤란해해요.", "love": "연애에서도 진지하고, 상대를 아끼는 마음을 행동으로 보여 줘요. 데이트할 가게도 시간도 꼼꼼히 정해 줘요. 다만 상대가 약속에 늦으면 짜증이 얼굴에 드러나기도 해요. 그럴 때는 먼저 '무슨 일 있었어?' 하고 물어보세요.", "work": "목표와 역할이 분명한 곳에서 힘이 나요. 팀을 모아서 마감대로 결과를 내는 역할로 의지받아요. 결론 없는 회의나 규칙이 애매한 곳에서는 짜증이 나기 쉬워요. 내가 먼저 진행 방식을 정해 버리면 잘 돌아가요.", "jobs": ["영업 매니저", "프로젝트 관리", "점장", "은행원"], "growth": "당신의 추진력은 남의 이야기를 듣는 시간이 있으면 더 도움이 돼요. 오늘은 누군가의 이야기를 끼어들지 말고 끝까지 들어 보세요.", "A": "망설이는 일이 적고, 그 자리에서 바로 정할 수 있어요. 반대를 받아도 이유를 차분하게 설명해요.", "T": "앞으로 생길 것 같은 문제를 미리 확인해요. 주변 반응도 잘 보니까, 부드러운 리더로 의지받아요."}, "ESFJ": {"catch": "다들 즐거운지, 늘 신경 쓰는 사람.", "overview": "주변 사람들이 즐겁게 지내는지 늘 신경 쓰는 사람이에요. 모임에서는 음료가 떨어진 사람이나 이야기에 못 끼는 사람을 바로 알아채요. 생일이나 축하할 일을 소중히 하고, 사람들이 기뻐하면 힘이 나요. 어느새 '이 사람이 있으면 분위기가 모여'라는 말을 듣고 있어요.", "strengths": ["사람과 사람을 이어요｜처음 만난 사람들 사이에 들어가서 '둘 다 강아지 키우지?' 하고 이야기를 이어 줘요.", "딱 좋을 때 말을 걸어요｜곤란해하는 사람에게 '뭐 도와줄까?' 하고 좋은 타이밍에 말할 수 있어요.", "축하를 소중히 해요｜친구 생일을 기억하고, 해마다 꼭 축하해요."], "pitfalls": ["사람들 반응이 너무 신경 쓰여요｜기쁘게 해 주고 싶어서 상대 눈치를 자꾸 봐요. 답이 안 와도 먼저 '바쁜가 보다' 하고 생각해 보세요.", "내 일정이 맨 마지막이에요｜다른 사람 일정에 맞추다 보면 내 볼일을 못 봐요. 일주일에 한 번, 나만의 일정을 먼저 넣어 보세요.", "부정당하면 풀이 죽어요｜열심히 하는 만큼 '틀렸어'라는 말이 아프게 와요. 들은 건 '방식'에 대한 말이지 당신에 대한 말이 아니에요. 다음엔 어디를 바꿀지만 생각해 보세요."], "relationships": "모임 연락 담당을 자주 맡아요. 곤란한 사람을 그냥 못 지나쳐서, 모두의 상담 상대가 되기도 해요. 같이 왁자지껄 즐겨 주는 사람과 잘 맞아요. 차갑게 대하면 오래 마음에 남아요.", "love": "좋아하는 사람에게는 자주 연락해서, 신경 쓰고 있다는 걸 전해요. 기념일 축하도 꼼꼼히 준비해요. 상대가 무심하면 '나 싫어졌나' 하고 불안해지기 쉬워요. 그럴 때는 용기 내서 '요즘 어때?' 하고 물어보세요.", "work": "사람과 함께하고, 고맙다는 말을 듣는 일이면 기운이 나요. 팀 분위기를 좋게 하고, 다들 일하기 편하도록 신경 쓰는 역할로 의지받아요. 경쟁만 있는 곳에서는 지치기 쉬우니, 서로 돕는 곳을 고르면 오래 다닐 수 있어요.", "jobs": ["호텔·서비스 직원", "교사", "웨딩 플래너", "요양보호사"], "growth": "남은 잘 챙겨도, 나 자신은 잊기 쉬워요. 오늘은 나만을 위해서 작은 간식을 사 보세요.", "A": "사람들 반응에 크게 휘둘리지 않고, 스스로 정해서 나아가요. 늘 밝아서 주변이 안심해요.", "T": "상대 마음을 세세하게 생각해서 배려가 아주 꼼꼼해요. 완벽하지 않아도 충분히 전해진다고 생각하면 마음이 편해져요."}, "ISTP": {"catch": "사용법은 만져 보면서 익히는 사람.", "overview": "'이거 어떻게 돼 있지?' 싶으면 먼저 만져서 확인하는 사람이에요. 새 가전이 오면 설명서를 안 읽고 이것저것 만져 보면서 사용법을 익혀요. 말수는 적어도, 곤란할 때는 침착하게 손을 움직여서 금방 고쳐요. 내 속도와 자유를 소중히 하는 타입이에요. 혼자 묵묵히 작업하는 시간이 가장 좋은 휴식이에요.", "strengths": ["하면서 익혀요｜이야기를 듣는 것보다 먼저 해 보는 게 더 빨리 늘어요.", "문제가 생겨도 당황하지 않아요｜컴퓨터가 갑자기 멈춰도 침착하게 원인을 찾아서 고쳐요.", "빠르게 처리해요｜필요한 것만, 가장 짧은 순서로 끝내요."], "pitfalls": ["말없이 고쳐 버려요｜아무 말 없이 고치니까 주변은 무슨 일이 있었는지 몰라요. 다 끝나면 '여기가 고장 나 있었어' 하고 한마디 해 보세요.", "위로하는 법을 몰라요｜친구가 울면 어떻게 해야 할지 몰라서 굳어 버려요. 말을 잘 못 해도 옆에 앉아서 고개를 끄덕여 주세요.", "앞일 계획을 세우기 어려워요｜그때그때 정하고 싶은 타입이에요. 중요한 마감만큼은 휴대폰 알림에 넣어 두세요."], "relationships": "넓고 얕게보다는, 마음 맞는 몇 명과 느슨하게 오래 지내는 타입이에요. 너무 붙어 있는 관계는 어려워서, 같은 방에서 각자 좋아하는 걸 할 수 있는 상대가 편해요. 말수가 적어도 곤란할 때 말없이 도와주니까, 조금씩 신뢰를 얻어요.", "love": "좋아하는 마음을 말로 하는 건 서툴지만, 행동에는 드러나요. 상대의 자전거를 고쳐 주거나, 무거운 짐을 쓱 들어 주거나. '좋아한다고 말을 안 해 줘'라는 말을 듣고 '자전거 고쳐 줬잖아' 하고 생각하기도 해요. 가끔은 짧아도 좋으니 말로도 전해 보세요.", "work": "내 손과 머리로 문제를 해결하는 일을 좋아해요. 기계나 도구, 데이터를 다루는 현장에서 문제 해결을 맡으면 의지받아요. 자잘한 규칙이나 긴 회의가 많은 곳은 좀 힘들어요. 내 방식대로 하게 해 주는 곳이면 편해요.", "jobs": ["기계·설비 엔지니어", "정비사", "시스템 유지보수·인프라 담당", "영상 편집·음향 스태프"], "growth": "'해 보면 알아'는 당신의 강점이에요. 오늘은 내가 한 일을 누군가에게 한마디만 설명해 보세요.", "A": "생각나면 바로 움직여요. 잘 안 되면 금방 다른 방법을 시도해요.", "T": "움직이기 전에 세세한 데까지 확인해요. 완성도에 신경 쓰니까 일이 꼼꼼해요."}, "ISFP": {"catch": "'좋다'고 느낀 쪽을 고르는 사람.", "overview": "나의 '좋아'를 아주 소중히 하는 사람이에요. 늘 다니는 귀갓길에도 노을이 예쁘면 멈춰 서서 사진을 찍어요. 말로 주장하기보다 옷이나 소지품, 만드는 것으로 나다움을 드러내요. 사람과 부딪치는 건 싫지만, 중요한 건 조용히 양보하지 않아요. 좋아하는 것에 둘러싸여 있으면 그것만으로 기운이 나요.", "strengths": ["색이나 소리의 차이를 알아요｜방 소품을 놓는 방법이나 옷 색 조합을 잘해요.", "사람을 탓하지 않아요｜실수한 친구에게도 '그럴 수도 있지' 하고 말할 수 있어요. 같이 있으면 마음이 놓인다는 말을 들어요.", "시간 가는 줄 모르고 만들어요｜과자 만들기나 그림을 시작하면 어느새 밖이 어두워져 있어요."], "pitfalls": ["싫은 걸 말 못 해요｜싸우기 싫어서 웃으며 넘겨요. 작을 때 '그거 좀 싫었어' 하고 말해 보세요.", "앞일 계획이 어려워요｜그날 기분을 소중히 하고 싶어서요. 자기 전에 내일 할 일을 하나만 정해 두세요.", "만든 것에 대한 의견에 풀이 죽어요｜만든 것과 내가 가까워서, 깎아내리는 말을 들으면 많이 우울해져요. 의견을 들을 때는 좋았던 점도 같이 물어보세요."], "relationships": "시끌벅적한 모임보다 마음 맞는 사람과 조용히 지내는 걸 좋아해요. 남 험담을 안 하고 누구에게나 부드럽게 대해서, 다들 편하게 느끼는 사람이에요. 속도를 맞춰 주는 사람이나, 좋아하는 것 이야기를 즐겁게 들어 주는 사람과 친해져요.", "love": "좋아하게 되면 손수 만든 걸 주거나, 은근히 챙겨 줘요. 상대가 좋아하는 색의 물건을 자기도 모르게 골라 사기도 해요. 마음을 말하기까지 시간이 걸리니까, 말보다 태도를 봐 주는 사람과 잘 맞아요.", "work": "느끼는 힘이나 손재주를 쓸 수 있는 일이 잘 맞아요. 사람이나 동물, 만드는 일에 정성껏 마주하는 일로 칭찬받아요. 실적 압박이나 경쟁이 심한 곳에서는 지치기 쉬워요. 내 속도로 차분히 완성할 수 있는 곳이 잘 맞아요.", "jobs": ["디자이너", "미용사·네일리스트", "파티시에·요리사", "동물보건사·애견미용사"], "growth": "당신이 느낀 건 누군가에게 보여 주면 더 잘 전해져요. 오늘 만든 것이나 발견한 걸 하나 친구에게 보여 주세요.", "A": "나의 '좋아'를 믿고 움직여요. 남들이 어떻게 생각할지 별로 신경 쓰지 않고, 좋아하는 걸 계속해요.", "T": "주변 마음에 아주 민감해서 세세하게 신경 써요. 마음에 들 때까지 몇 번이고 다시 만들기도 해요."}, "ESTP": {"catch": "'일단 해 보자'가 빠른 사람.", "overview": "생각하기보다 몸이 먼저 움직이는 사람이에요. 회의에서 이야기가 멈추면 '일단 해 봐요' 하고 제일 먼저 손을 들어요. 그 자리 분위기를 잘 읽어서, 문제가 생겨도 잘 빠져나가요. 이야기가 재밌고 어디 가도 금방 친해지니까, 어느새 무리의 한가운데에 있어요. 가만히 있는 시간이 길면 좀이 쑤셔요.", "strengths": ["움직임이 빨라요｜망설이기보다 하면서 생각해요. 세일이나 기회를 놓치지 않아요.", "순발력이 좋아요｜가려던 가게가 문을 닫았어도 금방 근처에서 다른 가게를 찾아와요.", "말을 잘해요｜처음 만난 사람과도 금방 농담을 주고받아요. 분위기가 활기차져요."], "pitfalls": ["준비 없이 시작해요｜하면서 생각하는 타입이에요. 중요한 일만큼은 시작하기 전에 '실패하면 어떡하지?'를 하나 생각해 두세요.", "같은 일의 반복에 질려요｜변화가 없으면 집중이 안 돼요. 지루한 작업은 타이머로 시간을 정해서 해 보세요.", "생각한 게 바로 입으로 나와요｜'그거 안 어울리지 않아?' 하고 말한 뒤에 아차 할 때가 있어요. 말하기 전에 숨을 한 번 들이쉬어 보세요."], "relationships": "놀자는 말은 대개 이 사람이 먼저 해요. 딱딱한 관계는 어려워서, 편하게 농담을 주고받는 사이가 좋아요. 분위기 맞춰 같이 움직여 주는 사람과는 금방 친해져요. 얽매이는 관계는 숨이 막혀요.", "love": "좋아하게 되면 바로 행동해서 데이트를 계속 신청해요. 같이 있으면 지루할 틈이 없는 연인이에요. 다만 미래 이야기가 나오면 자꾸 화제를 바꾸기도 해요. 중요한 이야기를 할 때는 휴대폰을 내려놓고 마주하면 신뢰가 훨씬 깊어져요.", "work": "변화가 많고 결과가 바로 보이는 일에서 힘이 나요. 영업이나 현장 일처럼 사람들과 움직이며 성과를 내는 자리에서 의지받아요. 계속 앉아 있는 일이나 규칙이 많은 곳에서는 지루해지기 쉬워요. 스스로 움직일 수 있는 범위가 넓은 곳을 고르세요.", "jobs": ["영업직", "이벤트 플래너", "스포츠 트레이너", "매장 운영"], "growth": "움직인 뒤에 조금 돌아보면 다음이 더 잘돼요. 오늘 하루를 마치면서 '다음엔 이렇게 하자'를 하나 정해 보세요.", "A": "자신감이 있어서 망설이지 않고 움직여요. 새로운 곳에도 척척 들어가서 자연스럽게 리더를 맡아요.", "T": "주변이 어떻게 생각하는지 잘 봐요. 하고 나서 돌아보고, 다음에 살릴 수 있어요."}, "ESFP": {"catch": "그 자리를 가장 즐기고 있는 사람.", "overview": "지금 이 시간을 마음껏 즐기고, 주변도 즐겁게 만드는 사람이에요. 재밌어 보이는 약속에는 고민하기 전에 '갈래!' 하고 답해 있어요. 표정이 풍부해서, 이야기만 해도 분위기가 밝아져요. 우울한 사람이 있으면 슬쩍 웃게 해서 기운을 북돋우니까, 자연스럽게 사람들이 모여요.", "strengths": ["분위기를 밝게 해요｜긴장된 자리에서도 당신의 리액션에 다들 웃어요.", "사람이 지친 걸 금방 알아채요｜노는 중간에 '잠깐 쉴까?' 하고 말할 수 있어요.", "어디서든 금방 어울려요｜전학이나 이동, 여행지에서도 금방 아는 사람이 생겨요."], "pitfalls": ["지쳐도 놀러 가요｜재밌어 보이면 잠이 부족해도 가 버려요. 다음 날 아침이 이른 날은 밤 약속을 거절해 보세요.", "돈이 자꾸 나가요｜그 자리의 즐거움을 먼저 챙기기 쉬워요. 갖고 싶은 게 있으면 사기 전에 하룻밤 기다려 보세요.", "무거운 이야기를 피해요｜분위기를 밝게 두고 싶은 마음이 커서요. 중요한 이야기는 노는 날과 다른 날에 짧게 시간을 내 보세요."], "relationships": "단톡방에서도 말을 많이 하는 분위기 메이커예요. 사람과 사람을 잘 잇고, 친구의 작은 변화도 알아채서 말을 걸어요. 우울한 날 조용히 이야기를 들어 주는 사람이 있으면 든든해요.", "love": "좋아하게 되면 마음이 바로 얼굴에 드러나요. 보고 싶으면 바로 연락하고, 데이트에서는 작은 깜짝 이벤트로 상대를 기쁘게 해요. 싸워도 다음에 만날 때는 벌써 웃고 있을 때가 많아요. 중요한 이야기는 미루기 쉬우니, 가끔은 먼저 '앞으로 우리 어떻게 하고 싶어?' 하고 물어보세요.", "work": "손님 반응을 바로 알 수 있는 일이 잘 맞아요. 접객이나 이벤트 같은 일에서 밝음과 배려로 칭찬받아요. 하루 종일 혼자 화면을 보는 일은 지쳐요. 사람과 이야기하면서 일하는 게 더 즐거워요.", "jobs": ["접객·판매 직원", "여행 가이드", "이벤트 스태프", "보육교사"], "growth": "조금 앞의 일정을 정해 두면 즐거운 시간이 더 오래가요. 오늘은 다음 주의 기대되는 일정을 하나 정해 보세요.", "A": "남의 눈을 별로 신경 쓰지 않고, 즐거울 때는 마음껏 즐겨요. 작은 실수 정도는 자고 나면 잊어요.", "T": "즐기는 동안에도 심심해 보이는 사람이 없는지 살펴요. 상대를 많이 생각하니까 깊이 신뢰받아요."}};
